window.ROH_EXTENSION.raceFeats = {"菲林(猫)":[{"name":"阿斯兰之血Bloodine of Aslan","meta":"种族专长（先决：菲林，等级8+）","description":"你有阿斯兰血统，且一定程度继承并掌握了来自体内血脉的力量。你获得以下增益：\n\n 属性值提升。你的力量、敏捷或魅力提升1，最多为22。\n\n 额外熟练。你从运动，求生或威吓中选择一个技能并获得其熟练。\n\n 狮心真击。每回合仅一次，若你在一次武器的攻击检定中具有优势，则你可使这次攻击额外造成1d6光耀伤害，且以此造成的光耀伤害无视目标的抗性。\n\n 血统纯化。当任何效应的前提需要你是阿斯兰，你的种族也被视为阿斯兰。"}],"沃尔珀(狐)":[{"name":"狐之狡黠 Fox's Cunning","meta":"种族专长（先决条件：沃尔珀，等级4+）","description":"沃尔珀敏捷、聪明，擅长护理尾巴。你获得以下效果：\n\n属性值提升。你的敏捷或魅力提升1，至多20。\n\n灵动闪避。当你被可见的近战攻击命中时，你可以采取反应使这次攻击具有劣势，这可能导致攻击失手。\n\n社交手腕。你从表演、欺瞒或游说中选择一项未熟练技能并获得其熟练。\n\n狡黠花招。你可以附赠动作执行影响动作。你以此影响一个能听见你声音的60尺内生物时，目标必须通过感知豁免（DC等同8+你魅力调整值+你熟练加值），否则陷入魅惑直到你下回合开始。"}],"乌萨斯(熊)":[{"name":"北境之力 Power of the North","meta":"种族专长（先决：乌萨斯，4级+）","description":"乌萨斯以强壮、耐寒、坚韧著称。你获得以下效果：\n\n属性值提升。你的力量或体质提升1，至多20。\n\n熊之怒意。当你已浴血，每回合仅一次，你发动的武器攻击或徒手打击可以额外造成1d6点相同类型的伤害。\n\n英雄气概。当你消耗英雄激励的时候，你可以获得等同你等级点临时生命值。此特性使用后需要完成短休或长休方可再次使用。\n\n勇毅抵抗。你在受到伤害时，可以采取反应以减少受到的伤害至多1d10+你熟练加值点。你每次长休之间可以使用此特性的次数等同熟练加值。"}],"佩洛(犬)":[{"name":"忠犬之誓 Oath of the Hound","meta":"种族专长（先决：佩洛，4级+）","description":"佩洛忠诚、嗅觉敏锐、心态坚定。你获得以下效果：\n\n属性值提升。你的感知或魅力提升1，至多20。\n\n佩洛坚定。你为对抗造成恐慌和魅惑状态的效应而作的豁免检定具有优势。\n\n敏锐追踪。你获得察觉技能熟练，若已熟练改为专精。并且你可以追踪24小时内留下的气味。\n\n鼓舞嚎叫。你可以使用附赠动作鼓舞人心，使你身边30尺内的所有盟友获得临时生命值，数值等于你的等级加上你的感知或魅力调整值，持续1分钟。此临时生命值存在期间，生物为对抗造成恐慌和魅惑状态的效应而作的豁免检定具有优势。此特性一经使用，你必须完成一次短休或长休才能再次使用此能力。"}],"鲁珀(狼)":[{"name":"狼群领袖 Alpha of the Pack","meta":"种族专长（先决：鲁珀，4级+）","description":"鲁珀家族观念强、且警惕，具有狩猎本能。你获得以下效果：\n\n属性值提升。你的力量或敏捷提升1，至多20。\n\n群体战术。每回合仅一次，若你在一次攻击中失手，且目标5尺内有你的未失能盟友，则你可使这次攻击检定获得+1d4加值。这可能导致攻击变为命中。\n\n狩猎协调。你可以在执行攻击动作时替换其中一次攻击，指挥一名能听见你的盟友发动奇袭，该盟友可以立即对你触及距离内的一个生物发动借机攻击。\n\n夜行猎手。你在黑暗中进行的隐匿检定具有优势，并且你的黑暗视觉距离增加30尺。"}],"瑞柏巴(鬣)":[{"name":"鬣狗战法 Hyena Tactics","meta":"种族专长（先决条件：瑞柏巴，等级4+）","description":"瑞柏巴团结、尚武，擅长荒地生存。你获得以下效果：\n\n属性值提升。你的力量或体质提升1，至多20。\n\n集群攻势。每回合仅一次，当你的攻击命中时，如果目标5尺内有你的未失能盟友，则你可以对目标额外造成 1d6 点挥砍伤害。\n\n荒地生存者。你获得对毒素伤害的抗性，并且你在野外环境为寻路、追踪或寻找食物而作的求生检定具有优势。\n\n坚韧不拔。你的死亡豁免具有优势，且在掷出19时即也可获得掷出20的好处。"}],"卡特斯(兔)":[{"name":"脱兔迅敏 Rabbit's Agility","meta":"种族专长（先决条件：卡特斯，等级4+）","description":"卡特斯敏捷、警觉、活泼。你获得以下效果：\n\n属性值提升。你的敏捷提升1，至多20。\n\n爆发移动。当你执行撤离动作后，直到本回合结束前，你的移动忽略困难地形。\n\n超然闪避。当你失败于一次敏捷豁免时，你可以将其改为成功。此特性一经使用，直到你完成一次长休前不可再次使用。\n\n灵敏本能。你从巧手、隐匿或特技中选择一项未熟练技能并获得其熟练。"}],"库兰塔(马)":[{"name":"骑士冲锋 Knight's Charge","meta":"种族专长（先决条件：库兰塔，等级4+）","description":"库兰塔奔跑迅速、耐力强，具有骑士传统。你获得以下效果：\n\n属性值提升。你的力量、体质或敏捷提升1，至多20。\n\n速度增强。你持握你熟练的武器时，你的基础速度可以额外增加5尺。\n\n疾驰冲锋。每回合仅一次，如果你直线移动至少10尺后立刻对一个目标发动近战攻击，这次攻击额外造成 1d6 点穿刺伤害，并且将目标推离5尺。\n\n持久耐力。你为中止或避免陷入力竭状态而作的豁免检定有优势，并且你不会因为力竭状态而降低速度。"}],"骏鹰":[{"name":"骏鹰之血 Blood of Hippogryph","meta":"种族专长（先决：骏鹰，4级+）","description":"骏鹰的血脉带来的矫健身手，让你即便是在穿行崎岖难行的崇山峻岭之中也如履平地。你获得以下增益：\n\n 属性值提升。你的选择一项属性提升1，至多22。\n\n 勇气步伐。当你持用一把你熟练的武器时，你的基础速度提升至40尺。\n\n 越野作战。你获得等同你移动速度的攀爬速度，且无视非魔法的困难地形。\n\n 超凡闪避。当你被一次可见的攻击命中时，你可以采取反应使得攻击失手。此特性一经使用，直到你完成一次短休或长休前不可再次使用。"},{"name":"帝国遗风 Imperial Legacy","meta":"种族专长（先决：骏鹰，8级+，已习得骏鹰之血）","description":"你获得以下增益：\n\n 属性值提升。你的选择一项属性提升1，至多22。\n\n 骏鹰威仪。你可以在执行攻击动作时，将其中一次攻击替换为执行影响动作。你以此影响一个能听见你声音的敌人时，目标必须通过感知豁免（DC等同8+你魅力调整值+你熟练加值），失败则陷入魅惑直到其下回合结束。\n\n 骏鹰法术。你知晓戏法荆棘之鞭。然后从下述两个法术中选择一个：三环风墙术、或四环行动自如，并加入你以风之庇护特性习得的法术中，且可以同样的方式免费施展一次或以法术位施展。当你施展所选法术时，作为施法动作的一部分，你可以发动一次武器攻击或徒手打击。"}],"黎博利(鸟)":[{"name":"自由之翼 Wings of Freedom","meta":"种族专长（先决条件：黎博利，等级4+）","description":"黎博利自由、轻盈、视力敏锐。你获得以下效果：\n\n属性值提升。你的敏捷或感知提升1，至多20。\n\n空中机动。你可以免费对自己施展飞行术，其施法属性为感知。你必须完成一次长休才能再次使用此能力。\n\n锐利目光。你对一个120尺内的目标执行搜索动作时，目标直到你下次回合开始前首次被攻击时该攻击具有优势，且期间不能受益于隐形。\n\n俯冲突击。每回合仅一次，当你对一个可见生物发动攻击时，如果你的位置高于它10尺及以上，或者你在坠落至少10尺后立即攻击，则这次攻击额外造成1d6点穿刺伤害。"}],"天马":[{"name":"银枪战术 Argent Tactics","meta":"种族专长（先决：天马，4级+）","description":"你掌握银枪天马的战斗技艺，你获得以下增益：\n\n属性值提升。你的力量、敏捷或魅力提升1，至多22。 \n天马真击。每回合仅一次，若你在一次武器攻击检定中具有优势，你可使得这次攻击额外造成1d6光耀伤害，并且以此造成的光耀伤害无视目标的抗性。 \n\n阵型协调。你可以在执行攻击动作时，将其中一次攻击替换为执行协助动作。当你执行协助动作，你可以协助最多距离你30尺远的目标。\n\n破阵冲锋。你的基础移动速度增加至40尺。"},{"name":"黄金誓言 Golden Oath","meta":"种族专长（先决：天马，8级+，已习得银枪战术）","description":"你的血脉力量完全觉醒，你获得以下增益：\n\n属性值提升。你的力量、敏捷或魅力提升1，至多22。 \n\n 光辉守护。你可以用附赠动作激发血脉能量，使自己和30尺内每个能听见你声音的盟友获得临时生命值，数值等于你的等级+魅力调整值，持续1分钟。此临时生命值存在期间，生物的移动速度增加10尺。此特性一经使用，直到你完成一次短休或长休前不可再次使用。\n \n 天马法术。你知晓戏法光耀祷词。然后从下述两个法术中选择一个：三环十字军披风、或三环加速术 ，并加入你以闪耀术法特性习得的法术中，且可以同样的方式免费施展一次或以法术位施展。当你施展所选法术时，作为施法动作的一部分，你可以发动一次武器攻击或徒手打击。\n\n血统纯化。当任何效应的前提需要你是天族时，你也被视为天族。"}],"梦魇":[{"name":"怯薛战法 Kheshig Tactics","meta":"种族专长（先决：梦魇，4级+）","description":"你掌握梦魇怯薛军的核心战术，获得以下增益：\n\n 属性值提升。你的力量、敏捷或魅力提升1，至多22。 \n\n 惧怖灵光。每回合仅一次，当你攻击命中对你恐慌的生物时，此次攻击额外造成1d12的心灵伤害。 \n\n 梦魇之语。你可以在执行攻击动作时，将其中一次攻击替换为执行影响动作。你以此影响一个能听见你声音的敌人时，目标必须通过感知豁免（DC等同8+你魅力调整值+你熟练加值），失败则对你陷入恐慌直到其下回合结束。\n\n 破阵冲锋。你的基础移动速度增加至40尺。"},{"name":"无尽征途 Endless Journey","meta":"种族专长（先决：梦魇，8级+，已习得怯薛战法）","description":"你是一名执着于自己天途的纯血梦魇，你获得以下增益：\n\n属性值提升。你的力量、敏捷或魅力提升1，至多22。 \n天途半道。当你在一次智力、感知或魅力豁免检定中失败时，你可以使其成功。此特性一经使用，直到你完成一次长休前不可再次使用。 \n梦魇法术。你知晓戏法心灵之楔。此外，你从下述两个法术中选择一个习得：三环恐惧术、或四环死神灵魄DMT，并加入你以惧怖威能特性习得的法术中，且可以同样的方式免费施展一次或以法术位施展。当你施展所选法术时，作为施法动作的一部分，你可以发动一次武器攻击或徒手打击。\n\n血统纯化。当任何效应的前提需要你是邪魔时，你也被视为邪魔。"}],"丰蹄(牛)":[{"name":"坚不可摧 Unbreakable","meta":"种族专长（先决条件：丰蹄，等级4+）","description":"丰蹄强壮、耐力出众，具有哲思妙想。你获得以下效果：\n\n属性值提升。你的力量、体质或智力提升1，至多20。\n\n哲思妙想。你获得一项已熟练技能的专精。\n\n强力闯越。你可以穿过任何生物占据的空间。穿过其空间不会消耗你额外的移动力，但你不能停在该空间。每回合仅一次，当你穿过一个体型小于等于你的生物时，它受到1d6钝击伤害并陷入倒地状态。\n\n众志成城。你可以附赠动作执行协助动作，并且可以协助最多距离你30尺远的目标。"}],"卡普里尼(羊)":[{"name":"才艺大师 Art Master","meta":"种族专长（先决条件：卡普里尼，等级4+）","description":"卡普里尼富有源石技艺天赋，看重艺术、以及角的保养。你获得以下效果：\n\n属性值提升。你的体质、智力或魅力提升1，至多20。\n\n文化传统。你选择一个你具有熟练且基于智力或魅力的技能，然后获得其专精。\n\n法术强效。当你施展一道法术并造成伤害时，你可以在其中一次伤害掷骰中加入你的熟练加值。\n\n艺术灵感。当你执行影响动作时，可以选择至多等同你魅力调整值个可以听见你声音的生物，这些生物将恢复等同你熟练加值点生命值，并且获得英雄激励。此特性一经使用，直到你完成一次长休前不可再次使用。"}],"埃拉菲亚(鹿)":[{"name":"自然之子 Child of Nature","meta":"种族专长（先决：埃拉菲亚，4级+）","description":"埃拉菲亚与自然和谐共处、以角传递情感，多于林地生活。你获得以下效果：\n\n属性值提升。你的敏捷、体质或感知提升1，至多20。\n\n森林学识。你从求生、自然、奥秘或宗教中选择一项已熟练技能，然后获得其专精。\n\n自然沟通。你 将法术 动物交谈 Speak with Animals 以及 纠缠术 Entangle 加入你以自然之友特性中，且可以用同样的方式施展。你使用此特性施展法术时，其不需要维持专注。\n\n野性面具。即便你只受益于轻度遮蔽，你也可以执行躲藏动作。"}],"曼提柯(狮蝎)":[{"name":"曼提柯技艺 Manticore Art of Ambush","meta":"种族专长（先决：曼提柯，4级+）","description":"你获得以下增益：\n\n 属性值提升。你的敏捷、智力或感知提升1，至多20。\n\n 致命伏击。你的攻击命中一个看不见你的敌人时，你可以让这次攻击视为造成重击。此特性一经使用，直到你完成一次短休或长休前不可再次使用。\n\n盲视。你获得10尺距离的盲视。\n\n 存在感降低。如果你在自己回合中没有移动或攻击，那么直到你下回合开始前，生物为揭露你的位置或意识到你存在而进行的感知（察觉）检定具有劣势。"}],"瓦伊凡(飞龙)":[{"name":"斗争血脉 Bloodline of Combat","meta":"种族专长（先决：瓦伊凡，4级+）","description":"你获得以下增益：\n\n 属性值提升。你的体质、感知或力量提升1，至多22。\n\n 荒蛮伟力。每回合仅一次，当你发动一次使用力量的攻击检定时，你可以使这次攻击具有优势，并在命中时额外造成1d6钝击伤害。你可使用此特性的次数等同于你的熟练加值，但仅会在该攻击命中时消耗次数。你在完成一次长休后会恢复所有已消耗的使用次数。\n\n 斗争抗性。你在一次力量、敏捷或体质豁免检定中失败时，可以将其改为成功。此特性一经使用，直到你完成长休前不能再次使用。\n\n 血统纯化。当任何效果的前提需要你是龙类生物时，你也被视为龙类。"}],"羽蛇":[{"name":"风雷羽术 Tempest Plumes","meta":"种族专长（先决：羽蛇，4级+）","description":"你进一步唤醒了羽蛇血脉中的机动与术法本能，获得以下增益：\n\n属性值提升。你的敏捷、智力或感知提升1，至多22。\n\n高空猎杀。每回合仅一次，当你对一个可见生物发动攻击时，如果你或者目标正在飞行或悬停于空中，则这次攻击额外造成1d6点穿刺伤害。\n\n锋羽防御。你未着甲时，基础AC等同13+你敏捷调整值，且你对闪电和雷鸣伤害具有抗性。"},{"name":"天穹蛇王 Sky-Serpent Sovereign","meta":"种族专长（先决：羽蛇，8级+，已习得风雷羽术）","description":"你已经能够短暂重现远古羽蛇统御天穹的姿态，获得以下增益：\n\n属性值提升。你的敏捷、智力或感知提升1，至多22。\n\n天穹再临。你从高空猎杀特性提供的额外伤害提升至2d6而非1d6。\n\n迅捷行风。你知晓戏法心灵之楔。然后从下述两个法术中选择一个：三环风墙术、或三环飞行术，并加入你以风雷术法特性习得的法术中，且可以同样的方式免费施展一次或以法术位施展。当你使用此特性施展所选法术时，其将无需专注维持。\n\n血统纯化。当任何效应的前提需要你是天族时，你也被视为天族。"}],"斐迪亚(蛇)":[{"name":"毒牙大师 Master of Venom","meta":"种族专长（先决：斐迪亚，4级+）","description":"斐迪亚具有敏锐的感官与毒理学造诣。你获得以下效果：\n\n属性值提升。你的敏捷、智力或感知提升1，至多20。\n\n剧毒攻击。每回合仅一次，当你造成穿刺、挥砍或毒素伤害时，你可以额外造成1d6点毒素伤害。\n\n蛇形机动。你获得20尺的攀爬速度，并且你可以移动穿过最窄1尺宽的空间，如同穿过困难地形。\n\n毒素免疫。你获得对毒素伤害的免疫，并且你免疫中毒状态。"}],"萨弗拉(蜥)":[{"name":"沙漠智者 Desert Sage","meta":"种族专长（先决：萨弗拉，4级+）","description":"萨弗拉是智慧的化身、也是沙漠之子。你获得以下效果：\n\n属性值提升。你的感知提升1，至多20。\n\n沙漠适应。你获得对火焰伤害的抗性，并且你在沙漠环境中为寻路、追踪或寻找食物而进行的 求生 技能检定具有优势。\n\n智慧长者。 你从历史、奥秘或调查中选择一项未熟练技能并获得其熟练。此外，你可以用附赠动作执行协助动作，且可以协助最多距离你30尺远的目标。"}],"扎拉克(鼠)":[{"name":"鼠之诡计 Rat's Cunning","meta":"种族专长（先决条件：扎拉克，等级4+）","description":"扎拉克行动敏捷、会囤积资源。你获得以下效果：\n\n属性值提升。你的敏捷或智力提升1，至多20。\n\n迅敏直觉。当你被一次可见的近战攻击命中时，你可以用一个反应使得这次攻击承受劣势，这可能导致攻击变为失手。\n\n盗贼技巧。你获得盗贼工具的熟练，并且你可以使用附赠动作执行躲藏动作、撬锁或解除陷阱。\n\n小巧灵活。你可以穿过任何体型比你大的生物所在空间。你未失能时，对你进行的借机攻击具有劣势。"}],"阿达克利斯(鳄)":[{"name":"提亚卡乌之力 Tiyakau's Might","meta":"种族专长（先决：阿达克利斯，4级+）","description":"你掌握了阿卡胡拉勇士的战斗技艺，获得以下增益：\n\n属性值提升。你的力量、体质或敏捷提升1，至多20。\n\n持久耐心。你完成短休后，恢复一次战斗狂热的使用次数。\n\n 雨林伏击。在林地中或在水下时，你的隐匿检定具有+5加值。此外，你在水中可以屏息的时间是正常的两倍。\n\n尾部强化。根据你的尾部类型获得相应增益：\n \n 粗尾巴：尾部伤害骰提升至1d10，你可以用附赠动作使用尾巴发动徒手打击。每回合仅一次，当你使用尾巴命中体型不超过大型的生物，可以迫使目标必须通过体质豁免（DC等同8+你力量调整值+你熟练加值）否则倒地。\n\n 细尾巴：尾部的载重提升至5磅，且你用尾巴进行擒抱时，目标为逃脱你擒抱而作的检定具有劣势。"}],"杜林":[{"name":"奇思妙想Durin Whimsy","meta":"种族专长（先决：杜林，4级+）","description":"你获得以下效果：\n\n 属性值提升。你的智力、感知或魅力升1，最多为20。\n\n科技装备。你准备过一些科技设备。每当你完成长休，你可以制造若干个普通魔法物品，数量同你熟练加值，从下述物品中选择：营养珠、净水珠、时间法球、方向法球、渊海蜡烛 、清洁石、永明提灯、羽落硬币。以此制造的物品在你完成一次长休后损毁。\n\n注法改造。你完成一次长休后，可以为武器和法器进行改造和注法，效应持续一天。你可以选择以下效应之一：\n\n将一把非魔法武器变成+1魔法武器。 \n\n将至多三枚普通弹药变成+1魔法弹药，命中后变为普通弹药。\n \n将一个普通奥术法器变成+1战法师魔杖。\n\n更多信息More Info\n\n际崖城：已知杜林拥有一座位于地下的名为“际崖城”的巨型地下城市，拥有先进的科技和各种方便的基建设施，是近乎乌托邦的理想城，乃是位于地下的桃花源。\n\n际崖城因为科技发达而生活富足，所以这里的杜林居民非常从容，对待集体中的各种思想和行为，也具有十分的包容性。\n\n因为杜林族乐观随和的天性，际崖城并未形成复杂的经济活动和的政治结构，也很少有内部矛盾，他们在政治上有根据影响的大小决定规模的公投，在经济上甚至没多少人在意货币这种东西。"}],"安努拉(蛙)":[{"name":"安努拉血脉 Anura's Bloodline","meta":"种族专长（先决：安努拉，4级+）","description":"你获得以下增益：\n\n 属性值提升。你的敏捷、智力或感知提升1，至多20。 \n 亚种强化。根据你的种群类型获得相应增益：\n\n——树蛙·强化毒素：你的毒性皮肤特性造成的伤害骰提升至2d6。以此造成伤害时，目标必须通过体质豁免（DC等同8+你体质调整值+你熟练加值），失败则中毒直到其下回合结束。以此中毒期间，生物不能执行反应。\n\n——雨蛙·隐匿大师：你可以使用附赠动作执行躲藏动作。即便你只受益于轻度遮蔽或半身掩护，你也可以执行躲藏动作。\n\n额外熟练。你从求生、自然或隐匿中选择一项未熟练技能并获得其熟练。\n\n本章内容来源：玩家投稿\n\n作者：...（3300629434）"}],"龙":[{"name":"龙脉觉醒 Dragon Blood Awakening","meta":"种族专长（先决：龙族，4级+）","description":"你觉醒了一部分真龙血脉的力量，获得以下增益：\n\n属性值提升。你选择一项属性提升1，至多22。\n\n超凡感官。你获得10尺盲视。\n\n赤霄剑术。每回合仅一次，当你使用近战武器对生物发动攻击时，你可以使这次攻击检定具有优势，并在命中时额外造成1d6雷鸣伤害。你可使用此特性的次数等同于你的熟练加值，但仅会在该攻击命中时消耗次数。你在完成一次长休后会恢复所有已消耗的使用次数。"},{"name":"真龙显化 True Dragon Manifestation","meta":"种族专长（先决：龙族，8级+，已习得龙脉觉醒）","description":"作为纯血龙族，你完全掌握了龙族的古老传承，获得以下增益：\n\n属性值提升。你选择一项属性提升1，至多22。\n\n传奇抗性。当你在一次豁免检定中失败时，你可以使其成功。此特性一经使用，直到完成一次长休前不可再次使用。\n\n龙威显赫。你知晓戏法神导术。然后从下述两个法术中选择一个：三环风墙术、或三环灵体卫士 ，并加入你以龙脉威能特性习得的法术中，且可以同样的方式免费施展一次或以法术位施展。你以此特性施展的法术专注不会因为受到伤害而被打断。\n\n血统纯化。当任何效应需要你是龙类生物时，你也被视为龙类生物。"}],"阿戈尔(水生)":[{"name":"深海科技 Deep Sea Technology","meta":"种族专长（先决条件：阿戈尔，等级4+）","description":"阿戈尔科技发达、族人冷静理性。你获得以下效果：\n\n属性值提升。你的智力或体质提升1，至多20。\n\n水下适应。你可以在水下呼吸，并且种族提供的游泳速度改为 50尺。\n\n科技装备。你准备过一些科技设备。每当你完成长休，你可以制造若干个普通魔法物品，数量同你熟练加值，从下述物品中选择：营养珠、净水珠、时间法球、方向法球、渊海蜡烛 、清洁石、永明提灯、羽落硬币。以此制造的物品在你完成一次长休后损毁。\n\n弱点分析。你进行的智力（调查）检定具有优势，并且你可以以一个附赠动作对60尺内的可见生物执行研究动作。当你这么做时，目标直到你下次回合开始前首次进行的豁免检定具有劣势。"}],"麒麟":[{"name":"天师传承 Tian Shi Legacy","meta":"种族专长（先决：麒麟，4级+）","description":"你掌握了更高阶的雷法技艺，获得以下增益：\n\n属性值提升。你的智力或魅力提升1，至多22。\n\n法理通明。当你施展一道造成闪电、雷鸣或心灵伤害的法术时，如果原本施法时间为动作，可以改为使用附赠动作施展。此特性一经使用，直到你完成一次短休或长休前不可再次使用。\n\n快速影响。你可以用附赠动作执行影响动作。如果你对一个30尺内可以听见你声音的盟友执行影响动作，你可以为其解除身上的一个魅惑或恐慌状态。"},{"name":"雷霆乾坤 Thunderous Universe","meta":"种族专长（先决：麒麟，8级+，已习得天师传承）","description":"你达到了天师级的修为，获得以下增益：\n\n属性值提升。你的智力或魅力提升1，至多22。\n\n破邪正雷。你造成闪电或雷鸣伤害时，忽略目标的伤害抗性。每当你在闪电或雷鸣伤害掷骰中掷出1，你就可以重掷，但必须接受新的结果。\n\n雷法精进。你知晓戏法奇术。然后从下述两个法术中选择一个：三环召雷术、或三环闪电束 \n ，并加入你以雷法初成特性习得的法术中，且可以同样的方式免费施展一次或以法术位施展。每当你为所选法术进行伤害掷骰时，你可以消耗并投掷一枚生命骰加入伤害掷骰中。\n\n血统纯化。当任何效应的前提需要你是天族时，你也被视为天族。"}],"德拉克(红龙)":[{"name":"生命之火Breath of Life","meta":"种族专长（先决：德拉克，4级+）","description":"你已理解红龙之血所代表着的意义，胸口燃起不熄的生命之火。你获得以下增益：\n\n属性值提升。你的体质或魅力提升1，至多22。\n\n复燃。你在完成短休后恢复一次追加灼烧特性的使用次数。\n\n光耀圣火。你通过追加灼烧特性造成的火焰伤害改为1d10光耀伤害，且在你造成光耀伤害时也可触发。\n\n闪耀复苏。当你造成了火焰或光耀伤害时，你可以使得自己或一名30尺范围内的可见盟友，恢复1d8+你职业等级的生命值。此特性一经使用，你必须完成短休或长休后方可再次使用。\n\n血统纯化。当任何效果的前提需要你是龙类生物时，你也被视为龙类。"},{"name":"幽冥之火Breath of Death","meta":"种族专长（先决：德拉克，4级+）","description":"你已理解红龙之血所代表着的意义，胸口燃起妖艳的幽冥之火。你获得以下增益：\n\n属性值提升。你的体质或魅力提升1，至多22。\n\n复燃。你在完成短休后恢复一次追加灼烧特性的使用次数。\n\n黯蚀冥火。你通过追加灼烧特性造成的火焰伤害改为1d10暗蚀伤害，且在你造成暗蚀伤害时也可触发。\n\n蚀骨燃烧。当你造成了火焰或暗蚀伤害时，你可以使得每个受此伤害的非构装生物开始燃烧。以此造成的燃烧每次造成1d10暗蚀而非原来的伤害。此特性一经使用，你必须完成短休或长休后方可再次使用。\n\n血统纯化。当任何效果的前提需要你是龙类生物时，你也被视为龙类。"}],"深海猎人":[{"name":"巅峰猎手Apex Predators","meta":"种族专长（先决：深海猎人，4级+）","description":"深海掠食者的血液在你血管中流淌，你获得以下效果：\n\n 属性值提升。你的力量、敏捷或体质提升1，最多为22。\n\n 精英猎人坚韧。你的生命值上限增加你当前等级数值，且随后每次升级生命值上限都会额外提升1。\n\n 掠食者血统：你从以下效果中选择一个获得。\n\n逆戟鲸。你消耗反应进行借机攻击时，可以发动两次而非一次武器攻击。此特性一经使用必须完成短休或长休方可再次使用。\n\n 寻猎鲨。你生命值降至0而没有立即死亡时，可以改为使生命值降至1。你必须完成一次长休后才能再次从此特质受益。\n\n剑旗鱼。你可以附赠动作执行疾走动作，如果你这么做了，你在本回合剩余时间内的移动忽略困难地形。你可以在每次长休之间使用此特性的次数等同你熟练加值。\n\n 座头鲸。你未着重甲时，AC获得+1加值。当你在一次体质豁免或死亡豁免中失败时，你可以改为成功。此特性一经使用，直到你完成一次长休前不可再次使用。\n\n 巨乌贼。当你用徒手打击命中一个不大于大型的生物时，你可以使用附赠动作尝试擒抱该目标。被你擒抱的生物同时陷入目盲状态。\n\n抹香鲸。当你执行推撞时，目标会在豁免失败时额外受到1d10+你力量调整值的伤害。\n\n 箱水母。当你一次攻击命中生物时，你可以迫使其进行一次体质豁免（DC=8+你的熟练加值+你的体质调整值）。若失败，其陷入中毒直到你的下个回合开始前。以此中毒期间，生物不能执行反应。你可以在每次长休之间使用此特性的次数等同你熟练加值。\n\n魔鬼鱼。你获得10尺盲视；每回合仅一次，你对一个看不见你的生物发动的攻击，在命中时额外造成1d10点钝击伤害。\n\n 巨海蛇。生物为抵抗你擒抱而作的豁免具有劣势。每当你的回合开始时，你还可以对一个因你受擒的生物造成等同你力量调整值的钝击伤害。"},{"name":"嵌合手术Chimeric Surgery","meta":"种族专长（先决：深海猎人，8级+，已习得巅峰猎手专长）","description":"你经过了多段深海猎人的海嗣融合改造手术，肉体强度足以突破人类极限。你获得以下效果：\n\n 属性值提升。你的力量、敏捷或体质提升1，最多为22。\n\n 精英猎人速度。你的步行以及游泳速度均提升10尺。\n\n 海嗣克星。你使用武器攻击海嗣类生物而失手时，可以选择重掷攻击检定中的其中一枚D20，但你必须接受重掷的结果。\n\n 潮汐狂怒。每回合仅一次，你使用你精通的军用近战武器发动的攻击命中时，你可以造成额外的武器伤害，数值等同你的体质调整值。"}],"萨科塔(天使)":[{"name":"圣洁铳仪 The Gun Ceremony","meta":"种族专长（先决：萨科塔，4级+，在萨科塔天赋中选择了铳械增益）","description":"你与自己的守护铳具有深入的联系，获得以下增益：\n\n属性值提升。你的敏捷或感知提升1，至多20。 \n\n祝福射术。当你使用铳械发动的一次远程武器攻击失手时，你可以消耗英雄激励再次发起一次具有优势的远程攻击。 \n\n圣洁真击。每回合仅一次，若你在一次远程武器的攻击检定中具有优势，则你可使这次攻击额外造成1d6光耀伤害，且以此造成的光耀伤害无视目标的抗性 。 \n\n更多信息More Info\n\n 萨科塔铳械：从不停歇的铳炮声，抵御着苦痛幽暗。\n\n铳是一种构造独特的中远距离杀伤武器，据传最先由拉特兰人发现，也因此成为了拉特兰的标志之一，但当地的铳械使用术对于外域来说过于先进和复杂。只有萨科塔人才会大量使用铳械，其他人则会选择更易于使用的远程武器。\n\n铳械是一种极其复杂的集成施术单元系统，用以发射蚀刻弹药。源石回路同时存在于铳械和蚀刻弹药上。击发铳械需要以源石技艺同时控制铳械和蚀刻弹药，并对它们做出一系列的细微操作。极高的使用难度换来的是极高的准确度、非常远的射程和持续的火力，这些优点完全掩盖了铳械比传统弓弩威力稍小的缺点。\n\n蚀刻弹药是铳械弹药的总称，由弹头、活性源石发射药、微型源石回路与弹壳四个部分组成。其中拉特兰生产的大部分铳械的蚀刻弹药的弹头为源石晶体打磨而成，活性源石发射药是经过特殊处理的源石蚀刻结晶，可以为激发弹药提供能量，微型源石回路也称“击发回路”，与铳械内部的施术单元组成完整的施术回路，是蚀刻弹药的核心元件，而弹壳则普遍由异铁合金制成。每一发蚀刻子弹内的施术单元都与拉特兰铳的结构相互对应。也就是说，不仅是铳器本身，就连它们发射的每一发蚀刻子弹都等同于术师的法杖，所以蚀刻子弹才会造价高昂。\n\n铳型武装在拉特兰受到系统化的管理。每一支铳械的生产与销售信息，以及每一位公民的持铳与使用资格，均由公证所记录在案。\n\n铳是大部分拉特兰人的首选武器，一位年满十二岁的拉特兰人在申报完成后，可以在公证所执行者的陪同下前往一家注册合规的铳械工坊挑选一把铳或其他铳型武装。在接下来的四年中接受系统的铳型武装操作培训，并在中等教育结业后考取拉特兰铳型武装运用许可协议，才能正式获得铳型武装的使用资格。此后，还需定期前往公证所，进行铳检等基本手续，以维持使用资格。如果违规用铳次数太多，可能会被公证所吊销铳型武装运用许可协议。未获得许可的拉特兰人可能会选择弩弓作为武器，因此拉特兰不仅仿制铳部件的技术十分发达，制造弩的技术也在同步发展。\n\n铳械在拉特兰信仰中常被认为是“律法的眷顾与恩典”“律法对拉特兰的守护”。依典籍记载，在律法的引导下，萨科塔发现了铳械与相关技术。萨科塔能更容易地掌握铳械的使用方法也被认为是律法赋予的天赋。铳械是拉特兰信仰的一种具象象征，无论是教袍和圣徒像，还是典籍封面和教堂花窗，其上都常能见到铳械与子弹的装饰元素。"}],"萨卡兹(恶魔)":[{"name":"延寿巫术 Elongated Lifespan","meta":"种族专长（先决：萨卡兹，4级+）","description":"属性值提升。你选择一项属性提升1，最多为22。\n\n技能熟练。你自选一个技能并获得其熟练，若已有则获得其专精。\n\n 萨卡兹战术。你受到一个生物的伤害时，可以将其标记。直到你下回合结束前，你首次对其命中的攻击额外造成1d6点同类型伤害。你同时只能以一个生物作为此特性的标记目标。"},{"name":"提卡兹之血 Blood of Teekaz","meta":"种族专长（先决：萨卡兹，8级+，已习得延寿巫术专长）","description":"属性值提升。你选择一项属性提升1，最多为22。\n\n 血统纯化。任何效应需要你是怪兽时，你也被视为怪兽。\n\n 传奇抗性。当你在一次豁免检定中失败时，你可以选择让其成功。你必须完成一次长休才能再次使用此特性。\n\n更多信息 More Info\n\n卡兹戴尔：萨卡兹人将自己的家乡称作卡兹戴尔（Kazdel），卡兹戴尔”在萨卡兹语言中指“家园”，或“家园所在的地方”。\n\n最初在卡兹戴尔地区生活的人是一群自相残杀的采猎文明。一位被记载为“远逐者”的猎手因不愿啃食同胞而遭放逐，却在银色山脉中获得了“文明的存续”（Civilight Eterna），它归来时，将这些采猎部落聚拢并建筑城市，并成为了第一任魔王，第一座卡兹戴尔也是在那时建立的。作为种族，他们的名字是“提卡兹”（Teekaz），即“有家之人”。\n\n广义的卡兹戴尔指由萨卡兹建立的整个君主制国家。卡兹戴尔历经过漫长而巨大的内战，曾多次被摧毁与重建。由于卡兹戴尔的不断遭毁，大量萨卡兹传说和文字记载都已佚失，使对其详细历史的研究变得困难重重。\n\n卡兹戴尔拥有一座大型移动平台，有时称其为卡兹戴尔城，又或者有时会因为这是萨卡兹唯一的移动城市，而将其直接称为卡兹戴尔。卡兹戴尔城是泰拉大地唯一一座萨卡兹聚居的移动城市，拥有独特的经济形态和社会文化。这座城市长期以死魂灵熔炉提供动力，并通过节点炉与管道为城内提供安全免费的能源。因曾被天灾轰击，城内无序地生长着巨型源石晶簇，悬挂着巫术祭坛的天空则不停洒落源石粉尘。城内建筑破败不堪。维多利亚战争之后，卡兹戴尔开始了现代化改造。\n\n卡兹戴尔城建设有城墙。经过现代化重建后，卡兹戴尔城墙装备了现代化的法术防御单元，能源供应也开始脱离对死魂灵的依赖，转而依靠“阿喃那”供能。\n\n第一座卡兹戴尔的城市极有可能位于哥伦比亚南方荒地的某处。但由于年代过于久远，其存在的痕迹极有可能已经被源石侵蚀湮没。而现今的卡兹戴尔活动范围则是根据早期资料推测而来的。\n\n萨卡兹巫术：作为泰拉大陆上可能是最早接触源石的族群，传统上萨卡兹人使用源石技艺的方式非常特殊，被称为“巫术”，并没有经过系统的研究与整理，十分强大而危险，对施术者本人也常会有不可预知的副作用。\n\n巫术与通常的法术不同，巫术来源于血统而非对源石能量的掌控，血统越纯粹，所能掌握的巫术力量越大。\n\n卡兹戴尔的古老萨卡兹的语言本身即为“巫术”的一种。一些萨卡兹部族语言会对萨卡兹人产生生理性的影响，无论此人生在何处、是否理解这门语言，心智皆会受到干扰，只有意志坚定者才能免疫古老语言的影响，可谓是萨卡兹血脉的诅咒。\n\n长时间接触源石使萨卡兹族群的一些生体记忆会与源石晶体混合，不断地在大地上流传，一代代地在萨卡兹感染者体内累积。一些一直传递着源石结晶的种群会将这些信息规划到一起、汇总起来，通过“巫术”等手段将这些信息展现出来，作出“预言”。“预言”晦涩难懂、语句破碎，但通常有着极高的准确性。\n\n由于萨卡兹文化对于源石的高依赖性，没有感染矿石病的萨卡兹某种意义上也是“不幸”的。\n\n延长寿命：萨卡兹以延长寿命的巫术而闻名，使得许多地位较高的萨卡兹寿命可以持续长达几个世纪甚至数千年。对于许多纯血统的萨卡兹人来说尤其如此，例如萨卡兹王庭的皇室成员，他们以“提卡兹之血”的继承者为荣。另一方面，矿石症的高感染率、低效的医疗体系以及频发的战乱等因素大大缩短了底层萨卡兹的寿命。"}],"女妖":[{"name":"女妖咒言 Banshees' Arts","meta":"种族专长（先决：女妖，4级+）","description":"尽管血统尚不纯粹，但你已初步理解了自己血脉所代表的意义。你获得以下增益：\n\n属性值提升。你的智力、感知或魅力提升1，最多为22。\n\n律令真言。你是言语的大师，你施展一道惑控学派法术时，你可以将其施法时间改为附赠动作。\n\n蕴法言语。每回合仅一次，若你以法术在对一个可以听见你声音的生物造成暗蚀伤害或心灵伤害，你可以额外造成1d6点伤害。如果该生物免疫于力竭状态则不受影响。"},{"name":"女妖之血 Bloodine of Banshee","meta":"种族专长（先决：女妖，8级+，已习得女妖咒言专长）","description":"你是纯血女妖，且一定程度继承并掌握了来自体内纯粹的女妖血脉的力量，你获得以下增益：\n\n属性值提升。你的智力、感知或魅力提升1，最多为22。\n\n宣告死亡。 你是律令法术的大师，你施展具有律令标签的法术时，如果对目标的生命值有要求，你可以短暂增强法术的力量，将该生命值要求额外提升等同你施法者等级的五倍。此特性一经使用，直到你完成一次长休前不可再次使用。\n\n 凋死真言。你通过蕴法言语特性造成的伤害提升至2d6而非1d6。\n\n 血统纯化。当任何效应需要你是精类生物时，你也被视为精类生物。\n\n更多信息More Info\n\n拉玛莲：女妖王庭的前任领袖，咒术大师，“六英雄”之一的女妖之主拉玛莲杜康珐丽丝，被称为河谷的女主人或大女妖。也是逻各斯（哀珐尼尔）的母亲。两个世纪以前，大女妖拉玛莲曾带领女妖一族在卡兹戴尔保卫战争中作出巨大贡献，在入侵卡兹戴尔的联军被击退后，玛莲选择舍弃女妖在卡兹戴尔的领地，带领残破的王庭向河谷迁徙。之后的时间里，元气大伤的女妖们在河谷休养生息，不再参与女萨卡兹与其他种族的纷争，而河谷也成为了女妖们最后的生息之地。\n\n女妖的河谷：“女妖的河谷位于卡兹戴尔的西北方的峡谷内。金色的密林与狭长迂回的谷口掩盖着一条密径，这条小径没有岔道，踏入其中的人亦不能折返只有女妖与尊贵的客人能够踏上它由咒文编织成的躯干。当你终于穿过这条小径，还需要踏上一座被浓雾包裹着的狭长石桥，踏着洁白的砖石继续步行。经过一夜步行，白昼送来的第一缕微光潜入山崖之间。向日出的方向望去，你终于来到了石桥的尽头，足以容纳数百人的阶梯式露台出现在你的面前。这时，你小心翼翼地摘下女妖们为客人戴上的面纱，得以清晰地见到河谷壮美的全貌。\n\n庞大的石质结构镶嵌在河谷的两侧，它们曾经是用来构筑堡垒的石料，如今被咒术重塑为灵动的形态，在山崖的环抱下托起庭院与凌空的走道，让人想起女妖曼妙的衣裙。临近正午，假如你跟上那些戏水的女妖，去到河谷的深处，冰晶般澄澈的溪流将在你的眼前汇聚，载着女妖们轻声的咏唱，向着河谷的更深处蜿蜒而去。太阳降落在金色的密林上，叶片的反光像是一簇簇被微风驯服了的火焰，在空中花园满溢的色彩之下燃烧。即便你忧心这样的景色会夺走一个人一生的时间，也请不要在黄昏时分匆匆离去。看，河谷的女主人身着午夜般的轻纱，在老妪的簇拥下踏出寝宫，而女妖们则会在此刻摘下花环与面纱。她将领唱，为在白昼与黑夜之间逝去的灵魂献上挽歌。这便是女妖的河谷。”"}],"石翼魔":[{"name":"塑石技艺Stone Shaper","meta":"种族专长（先决：石翼魔，4级+）","description":"尽管血统尚不纯粹，但你已初步理解了自己血脉所代表的意义。你获得下述增益：\n\n属性值提升。你的体质或力量提升1，最多为22。\n\n沃土磐岩。你在完成短休后恢复一次沃土守护特性的使用次数。\n\n石中精妙。你可以使用附赠动作并消耗一次沃土守护的使用次数获得60尺震颤感知，持续10分钟。你必须位于岩石表面上或是触碰着岩石的表面才能使用此震颤感知，不过其可以是天然的岩石，也可以是加工过的岩石。\n\n塑石者技艺。当你施展一道造成钝击伤害的法术时，你可以在其中一次钝击伤害掷骰中额外加入1d6点钝击伤害。"},{"name":"秽壤血脉Bloodline of Desecrated Earth","meta":"种族专长（先决：石翼魔，8级+，已习得塑石技艺专长）","description":"你是纯血石翼魔，且一定程度上继承并掌握了来自体内血脉的力量。你获得下述增益：\n\n属性值提升。你的体质或力量提升1，最多为22。\n\n主动石化。你可以使用魔法动作并消耗一次沃土守护的使用次数让自己进入石化状态。你也可以在自己回合开始时主动结束该状态。\n\n岩术精进。你知晓戏法抵抗术。然后从下述两个法术中选择一个：三环土阵壁KGE、或四环构装召唤术 ，并加入你以石之技艺特性习得的法术中，且可以同样的方式免费施展一次或以法术位施展。当你以此特性施展所选法术时，你获得等同你等级的临时生命值。\n\n血统纯化。当任何效应的前提需要你是元素生物时，你也被视为元素生物。"}],"血魔":[{"name":"血之契约 The Bloodpact","meta":"种族专长（先决：血魔，等级4+）","description":"尽管血统尚不纯粹，但你已初步理解了自己血脉所代表的意义。你获得以下增益：\n\n属性值提升。你的敏捷、感知或魅力提升1，至多为22。\n\n血爪强化。你尖牙利爪的伤害骰提升至1d8，且你可以使用附赠动作发动徒手打击。\n\n血腥视觉。你对具有血液而生命值未满的活体生物拥有30尺盲视。\n\n晦暗之威。你造成的暗蚀伤害忽略目标的抗性。"},{"name":"真祖血统 Primogenito Blood","meta":"种族专长（先决：血魔，8级+，已习得血之契约专长）","description":"你是纯血血魔，且一定程度继承并掌握了来自体内纯粹的血魔血脉的力量，你获得以下增益：\n\n属性值提升。你的敏捷、感知或魅力提升1，至多为22。\n\n瞬发杀戮。你可以使用附赠动作施展一道死灵学派的戏法。\n\n鲜血抵御。每回合仅一次，当你或者你30尺内的盟友被攻击命中时，你可以消耗一次掌控血液的使用次数，使该伤害减去1d10+你的魅力调整值。\n\n掌控鲜血。你在完成短休后恢复所有掌控血液的使用次数。\n\n真祖体质。当任何效应的前提需要你是亡灵生物时，你也被视为亡灵生物。\n\n更多信息More Info\n\n 杜卡雷：萨卡兹鲜血王庭的领袖，号称“君主之红”的血魔大君杜卡雷。外表和谈吐如同雍容华贵的年轻贵族男子，实际上残忍嗜血，喜爱鲜血的味道，看不起其他种族的人，对待其他同族态度也十分傲慢。\n\n拥有操纵血液的源石技艺，能够赋予血液生命形成源石技艺造物，还能通过“赐福”对生物和非生物进行扭曲的改造。即使是同为血魔的华法琳，也会对血魔大君感到恐惧。"}],"温迪戈":[{"name":"残酷巫术Cruel Witchcraft","meta":"种族专长（先决：温迪戈，4级+）","description":"尽管血统尚不纯粹，但你已初步理解了自己血脉所代表的意义。你获得以下增益：\n\n属性值提升。你的体质或力量提升1，最多为22。\n\n贪婪之攫。每回合仅一次，当你对你周围60尺范围内的一个你可见的生物造成伤害时，你可以额外对其造成1d6点暗蚀伤害。\n\n摄食生命。如果你使用暗蚀伤害杀死了一名中型或更大生物，你获得等同你等级的临时生命值。若目标生物种族为萨卡兹，则获得的临时生命值翻倍。"},{"name":"死亡主宰Death Dominion","meta":"种族专长（先决：温迪戈，8级+，任意温迪戈种族专长）","description":"你是纯血温迪戈，且一定程度上继承并掌握了来自体内血脉的力量，你获得以下增益：\n\n属性值提升。你的体质或力量提升1，最多为22。\n\n毁灭新生。当你的生命值降至0而未立即死亡时，你可以改为降至1。你获得等同你等级两倍的临时生命值。此特性一经使用，直到你完成长休前不可再次使用。\n\n坚韧意志。你拥有任意来源的临时生命值时，你免疫魅惑或恐慌状态。\n\n血统纯化。当任何效应需要你是精类生物时，你也被视为精类生物。"}],"死魂灵":[{"name":"亘古精魂 Ancient Spirit","meta":"种族专长（先决：死魂灵，4级+）","description":"你获得以下增益：\n\n属性值提升。你的智力、魅力或体质提升1，最多为22。\n\n历久弥坚。当你在一次智力、感知或魅力豁免中失败时，你可以使其成功。此特性一经使用，你必须完成长休才能再次使用。\n\n魂灵遗法。你习得两道法术：一环虔诚护盾、以及二环坚定神智 ，并加入你以死魂灵技艺习得的法术中，且可以同样的方式免费施展一次或以法术位施展。"},{"name":"溃心灾魂 Disaster Spirit","meta":"种族专长（先决：死魂灵，4级+）","description":"你获得以下增益：\n\n属性值提升。你的智力、魅力或体质提升1，最多为22。\n\n千载幽怨。当你发动一次攻击检定但失手时，你可以使其命中。此特性一经使用，你必须完成短休或长休才能再次使用。\n\n魂灵遗法。你习得两道法术：一环激愤斩、以及二环扰乱心智 ，并加入你以死魂灵技艺习得的法术中，且可以同样的方式免费施展一次或以法术位施展。"},{"name":"众魂永恒 Spiritual Eternal","meta":"种族专长（先决：死魂灵，8级+，任意死魂灵种族专长）","description":"你获得以下增益：\n\n属性值提升。你的智力、魅力或体质提升1，最多为22。\n\n魔法抗性。你为抵抗法术和魔法效应而作的豁免检定具有优势。\n\n希望与死仇。你习得一道法术：三环灵体卫士，或者三环复仇斩 ，并加入你以死魂灵技艺习得的法术中，且可以同样的方式免费施展一次或以法术位施展。"}],"巫妖":[{"name":"空间掌控 Master of Space","meta":"种族专长（先决：巫妖，4级+）","description":"尽管血统尚不纯粹，但你已初步理解了自己血脉所代表的意义。你获得以下增益：\n\n属性值提升。你的智力提升1，最多为22。\n\n空间操控。你习得并将下述法术加入你的空间术法特质习得的法术中：戏法空间操控ROH，以及一环封锁术ROH。你还可以同样的方式免费该法术施展一次。\n\n空间折叠。当你施展一道造成力场伤害或能将生物传送、放逐的法术时，你可以额外消耗一枚任何环阶的法术位，使得施法距离或传送距离翻倍。\n\n空间锚定。当一项环阶不高于你最大法术位的法术传送效应出现在你身边30尺内时，你可以采取反应来取消这次传送，为这次传送而作的任何动作都被浪费。"},{"name":"知识誊录者 Knowledge Transcriber","meta":"种族专长（先决：巫妖，8级+，任意巫妖种族专长）","description":"你是纯血巫妖，且一定程度上继承并掌握了来自体内巫妖血脉的力量，你获得以下增益：\n\n属性值提升。你的智力提升1，最多为22。\n\n虚空放逐。任何生物为了对抗你法术带来的放逐效果的而作的魅力豁免具有劣势。当你遭受放逐术或类似效应期间，你不会陷入失能。\n\n空间撕裂。当你施展一道造成力场伤害或能将生物传送、放逐的法术时，你可以投掷并消耗两枚生命骰，使得其中一个法术目标受到等同于你掷出的生命骰总和的力场伤害。\n\n血统纯化。当任何效应的前提需要你是亡灵生物时，你也被视为亡灵生物。\n\n更多信息More Info\n\n弗莱蒙特：巫妖一族的领袖，知识圣殿的看守者，担任“誊录”的弗莱蒙特，有着极高的源石技艺造诣和对空间法术的理解。大部分卡兹戴尔的巫妖曾在巫妖之主弗莱蒙特的带领下，离开卡兹戴尔并前往尚未建成的莱塔尼亚，为源石技艺的发展做出了巨大贡献，在此期间弗莱蒙特成为“巫王”赫尔昏佐伦的好友和导师。巫王成为暴君后，弗莱蒙特与其决裂并帮助选帝侯创造双子女皇，最终推翻了巫王的统治。之后的时间里，弗莱蒙特在莱塔尼亚担任高塔术士和恩瓦德路德维格大学教授，1100年女皇庆典事件后，弗莱蒙特带领巫妖族群返回卡兹戴尔，此后巫妖们承担了卡兹戴尔的秩序管理与现代化重建工作，同时也负责安抚卡兹戴尔魂灵熔炉之中的死魂灵。"}],"笞心魔":[{"name":"笞心迷钥 Djall's Keys","meta":"种族专长（先决：笞心魔，4级+）","description":"尽管血统尚不纯粹，但你已初步理解了自己血脉所代表的意义。你获得以下增益：\n\n属性值提升。你的智力、感知或魅力提升1，最多为22。\n\n笞心技艺。当你施展法术并要求一名生物进行感知豁免时，你可以使得该生物的豁免具有劣势。此特性一经使用，直到你完成一次短休或长休前不可再次使用。\n\n撕裂心灵。你施展一道惑控法术时，你可以立即对每个法术目标造成1d8点心灵伤害。"},{"name":"笞心垩主 Djall Arch-liar","meta":"种族专长（先决：笞心魔，8级+，已习得笞心迷钥专长）","description":"你是纯血笞心魔，且一定程度继承并掌握了来自体内纯粹的笞心魔血脉的力量，你获得以下增益：\n\n属性值提升。你的智力、感知或魅力提升1，最多为22。\n\n莫测者。你忽略任何能感知自己情感或阅读自己思想的效果，同时也包括非自愿的任何预言系法术。为了查明你的意图或诚意的感知（洞悉）检定具有劣势。\n\n摄魂夺心。你施展一道惑控法术时，你可以立即对法术目标造成的伤害提升至2d8而非1d8。\n\n低语密谈。你可以与120尺内的自愿盟友，或者任何被你魅惑或对你恐慌的生物进行心灵感应交流。\n\n血统纯化。当任何效应需要你是精类生物时，你也被视为精类生物。\n\n更多信息 More Info\n\n笞心魔的起源。相传在远古时代，笞心魔是萨卡兹中最早学会利用情感的族群。他们的祖先曾与梦魇的祖先争夺过恐惧的权柄，但最终选择了一条更为隐秘的道路。笞心魔的真名传统源于一次大灾变――当时一位强大的敌人试图通过真名诅咒整个王庭，笞心魔的领袖以自身为代价，将所有族人的真名封印于无形的咒语中，从此笞心魔的真名便无法被外人掌握。"}],"食腐者":[{"name":"朽败之躯 Corrupted Body","meta":"种族专长（先决：食腐者，4级+）","description":"尽管血统尚不纯粹，但你已初步理解了自己血脉所代表的意义。你获得以下增益：\n\n属性值提升。你的体质、感知或魅力提升1，最多为22。\n\n污秽免疫。你免疫中毒状态。\n\n腐朽强化。你可以在短休后恢复一次生命汲取的使用次数。\n\n秽蚀之触。每回合仅一次，当你以近战攻击命中一个生物时，可以花费一次生命汲取次数，使目标额外受到1d6暗蚀伤害，并且其无法恢复生命值，持续到你的下回合开始。"},{"name":"腐草枯荣 Decay and Flourish","meta":"种族专长（先决：食腐者，8级+，已习得朽败之躯专长）","description":"你是纯血食腐者，接近宗长的境界，获得以下增益：\n\n属性值提升。你的体质、感知或魅力提升1，最多为22。\n\n灵幛化身。当你浴血时，你可以附赠动作并消耗一次生命汲取次数来转化为灵幛形态持续1分钟。你身体化作由幛布组成的能量体，获得30尺飞行速度以及对挥砍、钝击、穿刺伤害的抗性以及暗蚀伤害免疫。灵幛形态下，你的攻击动作中的每次近战攻击，触及距离增加5尺，且额外造成等同你熟练加值的暗蚀伤害。\n\n不灭枯枝。当你受到伤害时，你可以采取反应并消耗一次生命汲取次数，使该伤害减少1d10+体质调整值。若此次伤害仍将你生命值降至0但并未将你杀死，你可以改为降至1。\n\n血统纯化。当任何效应需要你是植物生物时，你也被视为植物生物。\n\n更多信息 More Info\n\n孽茨雷：食腐者之王，枯朽王庭的宗长，萨卡兹六英雄之一，被称为“战争之神”。其年龄超过千岁，身上的布条是由无数座卡兹戴尔的战旗裁剪而成。他效忠的是萨卡兹这一存在本身，而非特蕾西娅或特雷西斯。他曾教导最后的纯血温迪戈博卓卡斯替，视其如子，对他的死亡深感惋惜。孽茨雷实力极强，能够汲取战场上所有死者的怨恨强化自身，肉身连血魔大君也不敢触碰，受伤时可用枯枝填补。他通常悬浮于空中，端坐于食腐者王座之上，俯瞰战局。\n\n食腐者与温迪戈：两族自古交好，食腐者之王曾亲自教导年轻的博卓卡斯替，使其成为威震乌萨斯的“爱国者”。博卓卡斯替最终离开卡兹戴尔，在切尔诺伯格战死，这一事件加深了食腐者对非萨卡兹魔王的疑虑。"}],"独眼巨人":[{"name":"冬牙先知 Fjall Seer","meta":"种族专长（先决：独眼巨人，4级+）","description":"你学会在破碎预兆中提炼出更清晰的结论，获得以下增益：\n\n属性值提升。你的智力、感知或体质提升1，至多22。\n\n远见增幅。你在完成短休后恢复众魂远见的使用次数。\n\n未来一瞥。当你通过仪式施展一道预言系法术时，你可以将施法时间缩短为附赠动作。此特性一经使用，必须完成长休才能再次使用。"},{"name":"诠释厄运 Doom Interpret","meta":"种族专长（先决：独眼巨人，8级+，已习得冬牙先知）","description":"你已经能够主动校准众魂低语中的噪音，将预兆转化为可用的战场结论，获得以下增益：\n\n属性值提升。你的智力、感知或体质提升1，至多22。\n\n预言精进。你知晓戏法传讯术。然后从下述两个法术中选择一个：三环洞烛先见DM、或四环预言术 ，并加入你以众魂远见特性习得的法术中，且可以同样的方式免费施展一次或以法术位施展。当你使用此特性施展所选法术时，你获得英雄激励。\n\n偏转悲剧。当你或者你可见的盟友在D20检定中掷出1时，可以视为掷出了N20。\n\n血统纯化。当任何效应的前提需要你是巨人时，你也被视为巨人。"}],"变形者子意识":[{"name":"拟态伴生 Mimic Familiar","meta":"起源专长（先决：变形者子意识，1级+）","description":"你可以分裂出拟态碎片协助战斗。你获得以下增益：\n\n伴生碎片。你习得寻获魔宠Find Familiar，并可以仪式且无需耗材地施展此法术。你以此施展该法术的施法属性是感知、智力或魅力（在你选取此专长时选择）。你以此方式召唤的魔宠使用幻身灵Changeling（CR1/2）数据，其懂得你会的语言，且属性值和熟练项与你一致。该魔宠是你的“子意识碎片”——它的外形由集群的黏液塑成。若你的魔宠生命值降至0或者存在时间超过1小时，它就会化为黏液消散。\n\n链接回音。当你执行攻击动作时，你用该动作进行的任何攻击可以从你的位置或你的魔宠的位置发出。每一次攻击的发出位置都由你决定。当有你的可见生物主动离开你魔宠的触及距离时，你也如同位于魔宠所处的空间内般对该生物进行借机攻击。"},{"name":"无数面孔 Countless Faces","meta":"种族专长（先决：变形者子意识，4级+）","description":"你已无需依赖法术就能塑造自己的外观。你获得以下增益：\n\n属性值提升。你的魅力、体质或智力提升1，最多为22。\n\n瞬时换面。你可以使用附赠动作变形为小型或中型的类人生物，或变回其真实形态。除体型以外，其各形态下游戏数据均相同。你着装或携带的任何衣物或装备都不会随之变化。以此特质变形期间，你的魅力属性检定具有优势。\n\n真身显露。在战斗开始的首轮中，你的攻击检定具有优势。"},{"name":"集群的一瞥 Glimpse of the Collective","meta":"种族专长（先决：变形者子意识，8级+，任意变形者子意识专长）","description":"你可以短暂获得如同主集群一样的完美拟态能力。获得以下增益：\n\n属性值提升。你的魅力、体质或感知提升1，最多为22。\n\n认知解构。你可以随意施展二环侦测思想，使用与拟态伴生相同的施法属性。\n\n完美拟态。当有任何类人生物面对你施展的惑控学派法术豁免失败后，你就可以记录其的生物数据。每次长休之间仅一次，你可以免费施展九环形体变化，使用与拟态伴生相同的施法属性，前提是你必须先前通过此特性获悉了变形对象的生物数据，且变形对象的挑战等级不能超过你等级的一半。\n\n无面者。你忽略任何能感知自己情感或阅读自己思想的效果，同时也包括非自愿的任何预言系法术。为了查明你的意图或诚意的感知（洞悉）检定具有劣势。"}],"鬼":[{"name":"我执业火 Atma-Graha Hellfire","meta":"种族专长（先决：鬼族，4级+）","description":"你获得以下效果：\n\n 属性值提升。你选择一项属性提升1，最多为20。\n\n 恶鬼业火。你知晓戏法控火术，以及一环炼狱叱喝。你可以在每次长休间免费施展此法术一次而无需法术位，或者你也可以用法术位施展此法术。你施展此法术的施法属性是魅力。\n\n 本相显露。每长休间仅一次，你在战斗中处于浴血期间，你可以附赠动作释放心中的狂性并显露本相。直到战斗结束前，你获得以下效应：\n\n 无畏。你具有对恐慌以及魅惑状态的免疫，但你无法维持专注或施展法术。\n\n 鲁莽。任何生物对你的攻击检定具有优势，你对任何生物的近战攻击也具有优势。\n\n 狂怒。进入本相显露后，你必须在每次开始回合时通过一次DC15的感知豁免。否则你必须直到回合结束前持续攻击在你开始回合时距离你最近的生物（优先敌人）。其他对你友善且你能听见其声音的生物可以通过影响动作进行DC15的魅力（游说）检定来帮助你终止此效应。\n\n 不屈。当你生命值降至 0 而没有立即死亡时，你可以改为使生命值降至1。然后本相显露的效应会提前结束。"}],"阿纳萨":[{"name":"轮回觉悟 Samsara Enlightenment","meta":"种族专长（先决：阿纳萨，4级+）","description":"你达到了对生死轮回的深刻理解，获得以下增益：\n\n 属性值提升。你自选一项属性提升1，至多20。\n\n 往生回响。完成一次长休后，你可以选择获得一项你未熟练的技能或工具的熟练项，持续至下次长休。这代表你唤醒了前世积累的知识。\n\n 天地和谐。你免疫恐惧状态，且你30尺内可以听见或看见你的盟友对抗恐惧的豁免检定具有优势。\n\n 濒死觉悟。你进行的死亡豁免具有优势。"}],"精灵(ROH)":[{"name":"长川生灵 Long River's Child","meta":"起源专长（先决：精灵，1级+，巨兽领域：流水）","description":"你的血脉与水元素共鸣，获得以下增益：\n\n水族本能。你获得30尺游泳速度，且可以在水中呼吸。\n\n水之治愈。当你施展一道法术时，选择30尺内的一个生物，你投掷并消耗至多两枚生命骰，令该生物恢复等于所掷出点数的生命值。你可以在每次长休之间使用此特性两次。"},{"name":"碧空倩影 Azure Sky's Grace","meta":"起源专长（先决：精灵，1级+，巨兽领域：气尘）","description":"你的血脉与风元素共鸣，获得以下增益：\n\n疾风步伐。你的基础步行速度提升10尺。\n\n风之气流。当你施展一道法术时，选择30尺内的一个生物，令其沿你选择的方向推离15尺。你可以在每次长休之间使用此特性两次。"},{"name":"林深尊者 Deepwood's Majesty","meta":"起源专长（先决：精灵，1级+，巨兽领域：自然）","description":"你的血脉与自然元素共鸣，获得以下增益：\n\n野性面具。即便你只处于轻度遮蔽的状态，只要这一轻度遮蔽由枝叶、大雨、落雪、雾气或其他自然现象提供，你也可以进行躲藏。\n\n森之束缚。当你施展一道法术时，选择30尺内你可见的一个地面生物，目标速度降为0且无法提升，直到其下个回合结束或者该生物将一次攻击替换为释放其自身。你可以在每次长休之间使用此特性两次。"},{"name":"光影旅人 Light and Shadow Walker","meta":"起源专长（先决：精灵，1级+，巨兽领域：光芒）","description":"你的血脉与光辉之力共鸣，获得以下增益：\n\n光辉掌者。你知晓戏法光亮术。当你施展此法术时，光亮术的持续时间延长至8小时。\n\n光之赠礼。当你施展一道法术时，直到你下一回合结束前，你散发出30尺球状区域日光，日光区域视为明亮光照，期间压制施法距离内任何生物的隐形状态。你可以在每次长休之间使用此特性两次。"},{"name":"奇境秘灵 Wonderland's Spirit","meta":"种族专长（先决：精灵，4级+，任意精灵种族专长）","description":"你从先史科技中得到启发，又或者你所信仰或侍奉的巨兽愿意为你提供帮助，你获得以下增益：\n\n属性值提升。你的敏捷、智力或感知提升1，至多22。\n\n往昔传承。你获得一项已熟练技能的专精。\n\n先史奇迹。你可以使用魔法动作呼唤奇迹的干预。你从你的巨兽遗泽对应的领域法术表中选择一道环阶不超过你熟练加值的法术（施法时间必须为动作），并将该法术作为执行此动作的一部分施展，无需法术位也无需对应的施法材料。直到你完成一次长休前，你都无法再次使用此特性。"}]};
window.ROH_EXTENSION.backgrounds = {"general":[{"label":"信使","name":"信使","english":"Messenger","abilities":"敏捷、体质、感知","feat":"幸运。","skills":"求生与自然。","tool":"制图工具 或 陆运载具 或 盗贼工具","equipment":"(A): 信使证件，背包（内有密封邮袋（卷轴匣），制图工具或盗贼工具，地图，指南针，铺盖，爪钩，细绳），旅行服装，3GP；(B): 5000 LMD（50GP）","description":"从一位公爵的耳目与喉舌，到追踪天灾足迹的天灾信使。作为穿梭于城镇与村落间的旅者，你背负着寄托思念的信件、隐秘的情报或是关乎生死的天灾预警。泥泞山路上的兽蹄印、暴雪中孤灯闪烁的驿站、盗匪横行的峡谷小道——这些构成你记忆的经纬。人们或许轻视你褴褛的斗篷，但国王与乞丐同样渴望你雪白信封里的只言片语。","url":"https://astratide.github.io/ROH-online/topics/第二章：角色资源/%E8%83%8C%E6%99%AF/%E4%BF%A1%E4%BD%BF.html"},{"label":"医生","name":"医生","english":"Medic","abilities":"智力、体质、感知","feat":"医疗师。","skills":"医药与洞悉。","tool":"医疗工具 或 草药工具。","equipment":"(A): 医护人员证件，公文包（内有医疗包、抗毒剂，草药工具或医疗工具，记事本），高档服装，14GP；(B): 5000 LMD（50GP）","description":"你在诊所、战地医院或移动城邦的医疗部门工作，直面伤痛、疾病和矿石病。你的职责是诊断、治疗和缓解痛苦。日复一日处理伤口、分析病症、安抚病人，让你掌握了扎实的医疗知识、精准的操作技巧，以及快速判断伤情严重程度的能力。你见过生命的顽强与脆弱，这让你对人性有深刻的洞悉，也深知在资源有限的环境下做出抉择的艰难。","url":"https://astratide.github.io/ROH-online/topics/第二章：角色资源/%E8%83%8C%E6%99%AF/%E5%8C%BB%E7%94%9F.html"},{"label":"佣兵","name":"佣兵","english":"Mercenary","abilities":"力量、体质、敏捷","feat":"凶蛮打手。","skills":"威吓与求生。","tool":"选择一种赌具，或者载具（陆运）。","equipment":"(A): 任意熟练的军用近战武器（至多10GP），任意赌具，背包（内有铺盖，口粮（3日份），撬棍），铁壶，旅行服装，14GP；(B): 5000 LMD（50gp）","description":"你的生活围绕着合同、冲突区和荒野展开。你受雇于公司、私人或秘密组织，在移动城邦的阴影地带、危险的废土或源石污染区执行任务。可能是安保、护送、侦察，或是更直接的武力行动。这让你精通各种武器、熟悉如何在恶劣环境下生存，并深刻理解暴力的代价与效率。你学会了快速评估威胁、讨价还价，以及在枪林弹雨或源石技艺对轰中活下来。","url":"https://astratide.github.io/ROH-online/topics/第二章：角色资源/%E8%83%8C%E6%99%AF/%E4%BD%A3%E5%85%B5.html"},{"label":"工人","name":"工人","english":"Laborer","abilities":"力量、体质、敏捷","feat":"警戒。","skills":"运动与察觉。","tool":"选择一种工具。","equipment":"(A): 工具（同上所选），撬棍 或 铲子，灭火器，铁壶，铁钉，1小包，旅行服装，8GP；(B): 5000 LMD（50gp）","description":"你的双手是谋生的工具，在移动城邦的引擎区、工厂流水线或基建维护现场劳作。你熟悉大型机械的轰鸣、金属的冰冷触感，以及完成一项体力活后的踏实感。这份工作给了你强健的体魄，对机械运转和结构稳固的直觉理解，以及在嘈杂或危险环境中保持警觉的能力。你对移动城邦的底层运作有着切身的体会。","url":"https://astratide.github.io/ROH-online/topics/第二章：角色资源/%E8%83%8C%E6%99%AF/%E5%B7%A5%E4%BA%BA.html"},{"label":"学生","name":"学生","english":"Student","abilities":"智力、感知、魅力","feat":"熟习。","skills":"调查与历史。","tool":"选择一种乐器或赌具，或书法工具。","equipment":"(A): 学生证件，帆布背包（装有笔记本，教科书），工具（同上所选），旅行服装（校服），8GP；(B): 5000 LMD（50gp）","description":"你的生活被课堂、书本和移动城邦的教育机构所占据。你学习理论知识、基础科学，或者源石技艺的原理。同学间的讨论、导师的指导，以及对未来的憧憬或迷茫构成了你的日常。这段经历教会了你如何快速吸收信息、分析问题，以及在图书馆或数据库中进行有效检索。你开始意识到，书本外的世界同样充满挑战。","url":"https://astratide.github.io/ROH-online/topics/第二章：角色资源/%E8%83%8C%E6%99%AF/%E5%AD%A6%E7%94%9F.html"},{"label":"白领","name":"白领","english":"White-collar","abilities":"智力、体质、魅力","feat":"熟习。","skills":"洞悉与游说。","tool":"文书伪造工具。","equipment":"(A): 公文包（装有香烟，文书伪造工具，笔记本），高档服装（西装），香水或提神剂，12GP；(B): 5000 LMD（50gp）","description":"你的日子在移动城邦的办公楼隔间或数据处理中心里度过。你处理文件、协调资源、参与会议，或是维护复杂的城邦管理系统。办公室政治、项目截止日期和重复性工作磨练了你的耐心、对细节的观察力，以及在条条框框内沟通协调的能力。日复一日的流程让你对规则和秩序异常敏感，也深知表面平静下可能暗藏的玄机。","url":"https://astratide.github.io/ROH-online/topics/第二章：角色资源/%E8%83%8C%E6%99%AF/%E7%99%BD%E9%A2%86.html"},{"label":"感染者","name":"感染者","english":"Infected","abilities":"力量、体质、感知","feat":"健壮。","skills":"洞悉与求生。","tool":"盗贼工具。","equipment":"(A): 通用抑制剂，防护面具，盗贼工具，撬棍，2小包，旅行服装，4GP；(B): 5000 LMD（50gp）","description":"源石结晶在你体内生长，迫使你活在歧视与病痛中。你学会隐藏症状、寻找黑市药物，或在矿场用性命换取抑制剂。这份苦难磨砺出你的意志力，也让你对他人痛苦异常敏感。你比任何人都清楚——活下去本身即是抗争。","url":"https://astratide.github.io/ROH-online/topics/第二章：角色资源/%E8%83%8C%E6%99%AF/%E6%84%9F%E6%9F%93%E8%80%85.html"}],"factions":[{"label":"罗德岛","name":"罗德岛","english":"Rhodes Island","abilities":"任意","feat":"取决于身份","skills":"任选1项技能","tool":"陆运载具 或 自选工具","equipment":"(A)：罗德岛雇员证件，背包（内有防护面具，通用抑制剂，铺盖），旅行服装，10GP； (B)：罗德岛雇员证件，50GP","description":"罗德岛是致力于解决源石病问题的制药公司与武装组织，有时也被视为卡兹戴尔巴别塔的流亡政府而存在。罗德岛本部舰船穿梭于各移动城邦间，收留感染者、研发药物并介入区域性危机，于世界多处国家和地区建立办事处，与多座移动城市签订贸易协定。罗德岛致力于创建感染者与非感染者和平共处的社会，以及解决感染者引发的各种事件，抗击极端感染者组织以及制止那些危害整片大地的威胁。\n\n罗德岛成员多为医疗科研人员或者外勤干员，其信条是为“为所有人而战”。在PRTS叛乱事件以后，罗德岛的本部从移动航母迁移到了临近哥伦比亚的一块移动地块上。尽管原来被所有人视为家园的罗德岛本舰已经被源石所彻底占领，你们也失去了一名值得信任的领袖。但不幸中的万幸，在充分的提前准备下，罗德岛并未受到太多的在人员、技术以及财产方面的损失——但你们清楚地意识到罗德岛要面对的挑战才刚刚开始。\n\n阵营身份：从以下几种预设身份中选择一种，然后获得对应的额外装备、技能熟练和起源专长。","url":"https://astratide.github.io/ROH-online/topics/第二章：角色资源/阵营/%E7%BD%97%E5%BE%B7%E5%B2%9B.html","identities":[{"title":"1. 外勤干员 Field Operator","text":"外勤干员携带武器在野外或危险区域执行任务，任务目标包括但不限于负责护送、侦察或清除威胁，有时要面对危险的源石污染和敌人攻击。在必要时刻，罗德岛派遣的外勤干员也会积极地参与进地方区域性危机中，或是进行调停工作，以及解决感染者引发的各种事件。外勤干员是罗德岛与外界联系和释放善意的桥梁，你们相信随着努力大地会变得越发美好。\n\n额外装备：自选熟练的简易武器，耳麦，通讯仪\n\n额外技能：求生\n\n起源专长：健壮"},{"title":"2. 后勤干员 Logistic Operator","text":"后勤干员在罗德岛舰船内维护设备、调度物资或分析数据。你确保能源、武器和医疗资源在任务中正常运转。后勤干员为了确保罗德岛本舰以及在外执行任务的外勤小队能够以最佳效率行动，往往需要付出极大的耐心以及具备细腻的观察力。当然，除了逗留在本舰，后勤干员有时也会随着外勤小队一起出发执行任务，或是在泰拉各地建立办事处提供补给支援。\n\n额外装备：自选工具\n\n额外技能：巧手\n\n起源专长：巧匠"},{"title":"3. 医疗干员 Medical Operator","text":"医疗干员们专职于诊断源石病、处理战场伤员或研发抑制剂。你与其他同僚一起通过自己的临床知识，在医疗部负责人的带领下推进源石病临床治疗或抑制剂开发。参与外勤任务时，医疗干员的急救或战地医疗知识能显著地提升战友的生存率，并为那些急需人道医疗援助的地区带来曙光。长期接触感染者的经验，使他们清楚地知道这种疾病有多致命（以及人们对这种疾病有多少误解）。\n\n额外装备：医疗工具，抗毒剂\n\n额外技能：医药\n\n起源专长：医疗师"},{"title":"4. 合作干员 Cooperative Operator","text":"合作干员们代表着泰拉大地上的其他组织与罗德岛达成合作。驻留本舰以协助罗德岛执行不同的外勤任务，或是交换情报。合作干员们有时会参与于罗德岛的任务以及战术简报会议，提出指导性意见或是进行学习。不过在于罗德岛展开深度合作的同时，他们同时也会确保自己原阵营的目标得到实现。合作干员通常在遇到重大分歧的时候保持中立的态度，并且向总部回报相关的信息。\n\n额外装备：所选阵营的证件，移动终端\n\n额外技能：游说\n\n起源专长：熟习"},{"title":"5. 罗德岛：自定义背景","text":"启用《塔莎的万事坩埚》扩展中的定制规则的战役，允许了玩家角色创作自己的自定义背景。在这种情况下，他们可以自己创作自己的背景身份设定，自选从背景中获得的属性值提升、装备、技能熟练以及起源专长。不过这种创作仍必须有一定的合理性，也就是创作的背景需要和他们所选的装备、技能和专长有一定叙事上的关联。\n\n属性值提升：任意\n\n额外装备：无\n\n额外技能：自选一项技能\n\n起源专长：自选一项起源专长"}]},{"label":"莱茵生命","name":"莱茵生命","english":"Rhine Lab","abilities":"智力、感知、体质","feat":"取决于身份","skills":"任选1项技能","tool":"医疗工具 或 自选工匠工具 或 文书伪造工具","equipment":"(A)：莱茵生命雇员证件，高档服装，公文包，手表，10GP； (B)：莱茵生命雇员证件，50GP","description":"莱茵生命是哥伦比亚顶尖的科研机构，总部位于移动城市特里蒙，致力于生命科学、化学制造和生物应用等前沿领域。机构分为十个专业科室，由总辖构件科统筹管理，下设五个科研科和四个事务科。莱茵生命鼓励科研人员自由立项，同时承接政府和企业的机密项目。近年来某些未公开项目扩大了招募规模，并有军方资源介入的传闻，这些项目可能涉及生物体的源石实验。机构内部存在一定的竞争关系，特别是生态科和能量科之间的派系斗争时有发生。\n\n莱茵生命最初由克丽斯滕·莱特以及塞雷娅联合创立。其中克丽斯滕一直作为整个公司最高部门的实际管辖者，但在世纪末的特里蒙弧光事件中，克丽斯滕驾驶万星园突破星荚前往了外层空间。此后莱茵生命迎来了一次巨大的人事变动。许多原本的科室主任出现了岗位调动，如今总辖构件科由同为创始人的塞雷娅代管，莱茵生命将在更具有约束力也道德规范的前提下开展更多的科学研究。而作为现执行顾问的赫默·奥利维亚所发起的《特里蒙科学伦理联合宣言》，也促成了哥伦比亚的科学伦理道德共识委员会的建立，现在的莱茵生命正在重新成为特里蒙乃至哥伦比亚学术界的焦点。\n\n阵营身份：从以下四种身份中选择一种，然后获得对应的额外装备、技能熟练和起源专长。你也可以自己编造新的身份。","url":"https://astratide.github.io/ROH-online/topics/第二章：角色资源/阵营/%E8%8E%B1%E8%8C%B5%E7%94%9F%E5%91%BD.html","identities":[{"title":"1. 科研部门研究员","text":"莱茵生命的科研人员们在结构科、能量科或源石技艺应用科等莱茵生命科研部门工作，日常包括实验设计、数据分析和理论验证。科员们的研究可能涉及生物结构改造、新能源开发或源石技艺应用等尖端领域。作为尖端技术的探索者，科研人员们需要平衡学术理想与项目保密要求，某些实验的伦理边界也经常引起争议和矛盾。\n\n额外装备：自选工具，放大镜，记事本（实验日志），提神剂，防护面罩\n\n额外技能：奥秘\n\n起源专长：源石技艺天赋 或 巧匠"},{"title":"2. 防卫科干员","text":"防卫科雇员们负责了莱茵生命设施的安保工作，保护机密研究和科研人员安全。他们的任务范围包括日常巡逻、异常事态处理和信息保密，具有相当高的权限。为了应对超出预期的实验室事故，警卫人员们也配备莱茵生命为其提供的防暴装置，经过特级防暴作战训练，护卫能力大大增强。某些项目的危险性，偶尔会让防卫科雇员们质疑自己保护的是科学进步还是危险实验。\n\n额外装备：自选熟练的武器（不超过10GP），抗毒剂，防护面罩，耳麦，通讯仪\n\n额外技能：察觉\n\n起源专长：警觉 或 健壮"},{"title":"3. 科学考察队员","text":"科学考察部门是莱茵生命扩大其认知版图的触角，穿越文明边界，将更多未知的自然知识带回泰拉社会。目前莱茵生命已在萨米北方的冰原等设有固定科考站，南方察帕特设有莱茵办事处。考察队员们前往各种偏远地区进行野外研究，任务包括样本采集、环境监测和建立临时科考站。科学考察队要面对极端环境和未知生物威胁，并在确保自身安全的前提下，定期将研究成果安全送回特里蒙总部。长期离群索居让他们对机构的内部斗争保持距离。\n\n额外装备：毯子，卷铺，手电筒，旅行服装，背包\n\n额外技能：求生\n\n起源专长：警觉 或 健壮"},{"title":"4. 事务科专员","text":"事务科专员们在商务科或工程科等事务部门工作，负责项目对接、资源协调或设施维护。日常包括合同谈判、设备采购和跨科室协作。事务科专员们深谙机构运作规则，他们可以在生态科与能量科的派系斗争中周旋，同时确保整个莱茵生命的正常运作。随着掌握的信息越来越多，事务科专员往往能察觉某些项目的异常之处。\n\n额外装备：公文包，高档服装，移动终端\n\n额外技能：游说\n\n起源专长：熟习 或 洞悉"},{"title":"5. 莱茵生命：自定义背景","text":"启用《塔莎的万事坩埚》扩展中的定制规则的战役，允许了玩家角色创作自己的自定义背景。在这种情况下，他们可以自己创作自己的背景身份设定，自选从背景中获得的属性值提升、装备、技能熟练以及起源专长。不过这种创作仍必须有一定的合理性，也就是创作的背景需要和他们所选的装备、技能和专长有一定叙事上的关联。\n\n属性值提升：任意\n\n额外装备：无\n\n额外技能：自选一项技能\n\n起源专长：自选一项起源专长"}]},{"label":"黑钢国际","name":"黑钢国际","english":"Blacksteel Worldwide","abilities":"力量、敏捷、感知","feat":"取决于身份","skills":"任选1项技能","tool":"载具（陆用） 或 自选工匠工具 或 文书伪造工具","equipment":"(A)：黑钢雇员证件，自选熟练的武器（可以是铳械），旅行服装； (B)：黑钢雇员证件，50GP","description":"黑钢国际是总部位于哥伦比亚的跨国安全承包公司，前身是哥伦比亚独立战争时期的雇佣兵团。在“巴伦矿场事件”后，黑钢逐渐脱离原有体系，积极发展国际业务。随着哥伦比亚对外事务的影响力与日俱增，黑钢国际迎来了业务发展的黄金期，成为广为人知的安全承包商之一。\n\n黑钢国际提供从保镖服务到军事介入的全方位安全解决方案，业务涵盖灾后后勤、工程抢险等专业领域。黑钢由三大业务部门构成：武装人力派遣部门负责主要作战力量，装备与应用技术部门研发测试武器系统，矿石病与生化威胁处置部门处理特殊危险源。\n\n黑钢国际外派的特勤雇员们会定期返回巴伦基地述职并接受考核，近年来因矿石病感染问题，黑钢内部许多雇员被感染，部分委托方不愿意雇佣身为感染者的雇员，导致黑钢在这方面接到的委托量和收入减少。同时另一方面，黑钢也开始与罗德岛合作处理感染者雇员事务。\n\n阵营身份：从以下四种身份中选择一种，然后获得对应的额外装备、技能熟练和起源专长。你也可以自己编造新的身份。","url":"https://astratide.github.io/ROH-online/topics/第二章：角色资源/阵营/%E9%BB%91%E9%92%A2%E5%9B%BD%E9%99%85.html","identities":[{"title":"1. 武装承包商","text":"作为黑钢国际最主要的作战力量，武装人力派遣部门的作战人员们必须在巴伦基地内接受最长为期两年的培训和考核才能开始执行任务。作战人员们通常接取类似要员保护、区域控制等各类安全合同。对于高危地区护卫、设施安保和紧急响应有着丰富的经验。虽然公司提供了标准装备和战术训练，但合同条款常将你们置于法律灰色地带。\n\n额外装备：气动手铳，气动子弹（20发），急救包\n\n额外技能：察觉\n\n起源专长：警觉 或 凶蛮打手"},{"title":"2. 装备测试员","text":"你在装备与应用技术部门工作，负责实地测试新型武器和防护装备。任务包括战场数据收集、设备极限性能评估和故障应急处理。你常在模拟战斗环境中检验装备可靠性，有时需在真实委托中做实战测试。新装备的潜在缺陷可能让你身处险境。\n\n额外装备：自选熟练的简易武器，机械工具\n\n额外技能：巧手\n\n起源专长：巧匠 或 健壮"},{"title":"3. 生化响应专员","text":"为应对矿石病引发的感染者危机，黑钢国际特别设立“生化防护响应人员”（Biochemical Protection \nResponse Staff , \nB.P.R.S.），以此延伸出灾后后勤、工程抢险等多个领域的安保服务。该部门隶属于矿石病与生化威胁处置部门，专门处理感染源泄露、生化污染等极端事件。雇员们在工作时穿戴全套防护装备，使用专业设备隔离和清除污染。长期接触高危环境使得许多专员面临感染风险，部门内的许多同事已与罗德岛建立医疗合作。\n\n额外装备：防护服，源石检测仪，抗毒剂\n\n额外技能：医药\n\n起源专长：警觉 或 健壮"},{"title":"4. 外勤行政专员","text":"外勤行政专员们来自行政总部，负责合同谈判、任务协调和客户对接。虽非不是战斗人员，但依然需随团队前往现场处理商务与后勤事务。你在委托方诉求和公司利益间寻找平衡，同时确保合同条款符合哥伦比亚及国际安全法规。近期黑钢国际的感染者雇员问题，一定程度上增加了这方面的谈判难度。\n\n额外装备：公文包，移动终端，高档服装\n\n额外技能：游说\n\n起源专长：熟习 或 洞悉"},{"title":"5. 黑钢国际：自定义背景","text":"启用《塔莎的万事坩埚》扩展中的定制规则的战役，允许了玩家角色创作自己的自定义背景。在这种情况下，他们可以自己创作自己的背景身份设定，自选从背景中获得的属性值提升、装备、技能熟练以及起源专长。不过这种创作仍必须有一定的合理性，也就是创作的背景需要和他们所选的装备、技能和专长有一定叙事上的关联。\n\n属性值提升：任意\n\n额外装备：无\n\n额外技能：自选一项技能\n\n起源专长：自选一项起源专长"}]},{"label":"卡兹戴尔","name":"卡兹戴尔","english":"Kazdel","abilities":"力量，体质，感知","feat":"取决于身份","skills":"任选1项技能","tool":"自选赌具 或 自选工匠工具 或 盗贼工具","equipment":"(A)：背包（内有铺盖，口粮（3日份），撬棍，链条），1小包，铁壶，旅行服装，4GP； (B)：50GP","description":"萨卡兹的故土，饱经战乱的地区。卡兹戴尔内部政权更迭频繁，内战不断，常年受到周围国家的敌视。卡兹戴尔文化崇尚血统与战斗力，住民感染者比例极高。在卡兹戴尔近千年来持续不断地战争、覆灭与重建下，萨卡兹们有的渴求着向诸国复仇，而有的早已疲惫于战争。曾经的双王共治时期，在巴别塔以及军事委员会的共同领导下，曾使得卡兹戴尔其得到过短暂的稳定。但在随后因为复仇与和平的理念争端而引致的双王内战，还是使得卡兹戴尔再次陷入战争的混乱之中。\n\n在双王内战以一方领袖遇刺而草草结束后，卡兹戴尔军事委员会控制了卡兹戴尔唯一的移动城市，以强权维持着这里的秩序。在部分萨卡兹王庭成员回归后，军事委员会也积极地开始对卡兹戴尔实行现代化改造。然而，在军事委员会随后主导的伦蒂尼姆战争中，摄政王的失踪，和佣兵们惨重的死伤也使得主战派的力量遭到了极大的削弱。如今，重新建立起的巴别塔再次和军事委员会达成合作的局面，使得卡兹戴尔似乎又回到了那段双王共治的时期——尽管如今双王皆已永远地离开了萨卡兹们。\n\n阵营身份：从以下几种预设身份中选择一种，然后获得对应的额外装备、技能熟练和起源专长。你也可以自己编造新的身份（此时仅获得一项自选技能熟练和自选起源专长）。","url":"https://astratide.github.io/ROH-online/topics/第二章：角色资源/阵营/%E5%8D%A1%E5%85%B9%E6%88%B4%E5%B0%94.html","identities":[{"title":"1. 拾荒者","text":"拾荒者们在废墟和污染区翻找可用的金属零件或源石碎片，在战后的城市废墟中搜寻可用物资，拆卸武器零件或挖掘被掩埋的能源，靠贩卖废料换取食物和抑制剂。拾荒者们对卡兹戴尔的管道和小巷地形，也对卡兹戴尔荒野有充分的了解，这些信息帮助他们避开被佣兵团或委员会士兵控制的区域。\n\n额外装备：铲子，盗贼工具\n\n额外技能：求生\n\n起源专长：酒馆斗殴者"},{"title":"2. 情报贩子","text":"情报贩子们在帮派和佣兵团之间买卖消息。他们懂得如何用秘密换钱，但显然面对那些穷凶极恶的买家，也必须分出精力时刻警觉确保自己不被灭口。情报贩子们会随机地在疤痕商场的暗巷或是荒野上的营地里出现，向任何可能的潜在买家兜售秘密，那些军阀的动向或是废墟的坐标往往是他们最感兴趣的话题。\n\n额外装备：文书伪造工具 或 制图工具\n\n额外技能：欺瞒\n\n起源专长：警觉"},{"title":"3. 流亡战士","text":"流亡战士们因战乱失去家园，靠手中武器做着佣兵或是流寇。他们或许曾经有着可靠的后盾，但战争已经夺走了他们的队伍和指挥官。如今，许多流亡战士仍在寻求能容身的势力。\n\n额外装备：铁面具，自选熟练的简易武器\n\n额外技能：威吓\n\n起源专长：凶蛮打手"},{"title":"4. 巴别塔联络员","text":"巴别塔的联络员们代表着重建的巴别塔组织在卡兹戴尔活动，负责与军事委员会协调合作、传递情报或救助难民。行走在昔日战友与当前当权者之间，他们通常需要维护如今卡兹戴尔脆弱的和平，又要提防复仇派破坏这来之不易的联合局面。\n\n额外装备：自选工匠工具 或 医疗包\n\n额外技能：巧手\n\n起源专长：幸运"},{"title":"5. 卡兹戴尔：自定义背景","text":"启用《塔莎的万事坩埚》扩展中的定制规则的战役，允许了玩家角色创作自己的自定义背景。在这种情况下，他们可以自己创作自己的背景身份设定，自选从背景中获得的属性值提升、装备、技能熟练以及起源专长。不过这种创作仍必须有一定的合理性，也就是创作的背景需要和他们所选的装备、技能和专长有一定叙事上的关联。\n\n属性值提升：任意\n\n额外装备：无\n\n额外技能：自选一项技能\n\n起源专长：自选一项起源专长"}]},{"label":"莱塔尼亚","name":"莱塔尼亚","url":"https://astratide.github.io/ROH-online/topics/第二章：角色资源/阵营/%E8%8E%B1%E5%A1%94%E5%B0%BC%E4%BA%9A.html","identities":[{"title":"1. 高塔学徒","text":"你在大学内学习基础音乐或源石技艺理论，或已经进入某座法术高塔进修。你对音乐或法术有些自己的见解，但日常工作仍只能枯燥地抄写法术卷轴或打扫实验室。\n\n额外装备：法术高塔证件，书法工具，法术卷轴（自选戏法）\n\n额外技能：奥秘\n\n起源专长：魔法学徒（法师）或 源石技艺天赋"},{"title":"2. 贵族后裔","text":"你继承了一个没落贵族头衔。你有参加宫廷宴会的经验，但如今你正在想办法维持家族所剩不多的产业。\n\n额外装备：血统证件，易容工具或自选乐器，高档服装，宝石（10GP）\n\n额外技能：游说\n\n起源专长：幸运"},{"title":"3. 巡回乐师","text":"你在自己的乐团、各城邦的广场或酒馆演奏乐器，已有一定名气。你的收入依赖贵族佣金或是观众的打赏。\n\n额外装备：自选乐器，记事本（乐谱）\n\n额外技能：表演\n\n起源专长：音乐家"},{"title":"4. 城镇居民","text":"你遵纪守法地在移动城市内或聚落中生活。你可能经营自己的小生意，或者为贵族或者高塔的术师们服务。\n\n额外装备：书法工具 或 自选乐器，放大镜\n\n额外技能：巧手\n\n起源专长：熟习"},{"title":"5. 莱塔尼亚：自定义背景","text":"启用《塔莎的万事坩埚》扩展中的定制规则的战役，允许了玩家角色创作自己的自定义背景。在这种情况下，他们可以自己创作自己的背景身份设定，自选从背景中获得的属性值提升、装备、技能熟练以及起源专长。不过这种创作仍必须有一定的合理性，也就是创作的背景需要和他们所选的装备、技能和专长有一定叙事上的关联。\n\n属性值提升：任意\n\n额外装备：无\n\n额外技能：自选一项技能\n\n起源专长：自选一项起源专长"}],"description":"莱塔尼亚帝国是双子女皇统治的艺术与法术之国。以崔林特尔梅为首都，双子女皇的黑白高塔作为帝国宫廷的核心，通过神圣的金律乐章颁布政令，传递给九个选地侯统治的其他大区，以及其下辖的贵族高塔或是各个移动城市和城镇。莱塔尼亚法术氛围非常浓厚，当地的源石技艺普及率极高，且多与音乐相结合，这为莱塔尼亚带来了繁荣的音乐艺术，并曾使莱塔尼亚对感染者持更宽容的态度。\n\n在莱塔尼亚，音乐厅与法术高塔学院遍布城邦，现代源石技艺学说在法术协会以及各个大学的推动下下迅速发展。虽然莱塔尼亚仍保留大部分贵族制度，阶级分明，但那些经历过曾经巫王残暴统治时代的老人以及一些新生代，许多都不再对贵族抱有敬意。如今，在学术氛围更为浓厚的现代莱塔尼亚，血统论开始被抛弃，公民的法术天赋和音乐造诣一定程度上决定了其社会地位。\n\n阵营身份：从以下几种预设身份中选择一种，然后获得对应的额外装备、技能熟练和起源专长。你也可以自己编造新的身份（此时仅获得一项自选技能熟练和自选起源专长）。"},{"label":"乌萨斯","name":"乌萨斯","english":"Ursus","abilities":"力量，体质，感知","feat":"取决于身份","skills":"任选1项技能","tool":"自选工匠工具 或 盗贼工具 或 自选赌具","equipment":"(A)：厚重大衣，毯子，伏特加（1瓶），自选工具（同上），旅行服装，8GP； (B)：50GP","description":"乌萨斯帝国雄踞于泰拉大地的北部，幅员辽阔，自然环境严酷，历经十多年来的穷兵黩武以及掠夺拥有极其雄厚的军事资本。以圣骏堡为首都，乌萨斯皇帝以及帝国议会通过内卫部队、数十个隶属于各个公爵的集团军以及各个城市的地方军警，控制着整个庞大的军事帝国。尽管如此，掌握了新兴工业和资本的新贵族仍在与旧贵族和军方在暗处作着激烈的政治斗争。\n\n乌萨斯的平民百姓为帝国的扩张源源不断提供着兵源和资源，同时还要遭受特权阶层的剥削和欺凌，地位较为低下。在感染者政策方面，乌萨斯的感染者遭受着系统性压迫，甚至设里了感染者纠察队来搜捕感染者，许多歧视性政策形成了完整的奴役链条。民众不得不在严苛秩序与不同的生存压力间挣扎，而资源的匮乏也催生了底层黑市和各种走私行为。\n\n阵营身份：从以下几种预设身份中选择一种，然后获得对应的额外装备、技能熟练和起源专长。你也可以自己编造新的身份（此时仅获得一项自选技能熟练和自选起源专长）。","url":"https://astratide.github.io/ROH-online/topics/第二章：角色资源/阵营/%E4%B9%8C%E8%90%A8%E6%96%AF.html","identities":[{"title":"1. 帝国军人","text":"帝国的军人们服役于乌萨斯正规军队，可能隶属于某位公爵的集团军、地方卫戍部队或感染者纠察队。军人的日常包括边境巡逻、镇压暴乱或执行军事演习。严苛的军纪和上级的命令支配着帝国军人的生活，他们深知在乌萨斯军队中，服从往往比思考更重要。一些职衔更高的帝国军官通常有着更高的自主权，也能在严厉而紧绷的军事制度下分出精力思考何为帝国的荣耀。\n\n额外装备：制式军牌证件，自选武器（不超过10GP）\n\n额外技能：威吓\n\n起源专长：凶蛮打手 或 健壮"},{"title":"2. 贵族后裔","text":"你体内流淌着乌萨斯贵族的血脉，无论你对此骄傲抑或是摒弃，你已经凭此度过了一段富裕而无忧无虑的童年。你曾经学习过如何管理封地资产，或为家族在议会中的立场奔走。贵族身份对于贵族后裔们而言既是护身符也是枷锁，迫使着他们不得不时刻权衡荣耀与生存的界限。\n\n额外装备：血统证明，高档服装，香水 或 \n提神剂，名贵红酒（10GP）\n\n额外技能：游说\n\n起源专长：熟习 或 \n音乐家"},{"title":"3. 流亡者","text":"你因感染矿石病、触犯军规或得罪权贵而被迫逃离乌萨斯。如今你在荒野的废弃据点躲藏，或在黑市用假身份勉强维生。纠察队和赏金猎人的追捕让你不敢在一个地方久留，而资源的匮乏迫使你学会在极端环境中生存。\n\n额外装备：任意伪造证件，撬棍、铁壶\n\n额外技能：求生\n\n起源专长：幸运"},{"title":"4. 城镇居民","text":"你在乌萨斯某移动城市或是小镇的学校、医院、工厂或矿场劳动，用知识或体力换取微薄的报酬。你必须总是时刻提防自己会不会被感染。\n\n额外装备：防护面具，撬棍，铁壶，自选工具\n\n额外技能：巧手\n\n起源专长：熟习 或 幸运"},{"title":"5. 乌萨斯：自定义背景","text":"启用《塔莎的万事坩埚》扩展中的定制规则的战役，允许了玩家角色创作自己的自定义背景。在这种情况下，他们可以自己创作自己的背景身份设定，自选从背景中获得的属性值提升、装备、技能熟练以及起源专长。不过这种创作仍必须有一定的合理性，也就是创作的背景需要和他们所选的装备、技能和专长有一定叙事上的关联。\n\n属性值提升：任意\n\n额外装备：无\n\n额外技能：自选一项技能\n\n起源专长：自选一项起源专长"}]},{"label":"卡西米尔","name":"卡西米尔","english":"Kazimierz","abilities":"敏捷，智力，魅力","feat":"取决于身份","skills":"任选1项技能","tool":"自选赌具 或 自选工匠工具","equipment":"(A)：手表，文件夹（合同），提神剂，记事本，旅行服装，20GP； (B)：50GP","description":"卡西米尔作为骑士与商业之国，其广袤的平原与山陵也是库兰塔们的故乡。在现代卡西米尔，传统的骑士精神与利益至上的商业思想正在此地激烈地交锋。以大骑士领卡瓦莱利亚基为首都，监正会与商业联合会分别代表着骑士阶级和资本阶级，共同治理着卡西米尔的各个城邦，形成了二元政治的格局。军事上，卡西米尔依靠着数个征战骑士团抵御着东北方向虎视眈眈的乌萨斯帝国，其引以为傲的银枪天马骑士团组成的集群冲锋在旧时代曾让乌萨斯的高速战舰群折戟沉沙。\n\n随着商业联合会将骑士竞技商业化的进程，著名的卡西米尔骑士特别锦标赛在每年都为各企业牟取暴利的同时，使得竞技骑士沦为娱乐明星，也让资本企业逐渐垄断了城邦的物价和工作机会。在感染者政策方面，虽然卡西米尔近年对感染者放宽了许多政策，但这仍实际上地构成了进一步的压榨——感染者骑士和劳工们依然没有自己的选择。\n\n阵营身份：从以下几种预设身份中选择一种，然后获得对应的额外装备、技能熟练和起源专长。你也可以自己编造新的身份（此时仅获得一项自选技能熟练和自选起源专长）。","url":"https://astratide.github.io/ROH-online/topics/第二章：角色资源/阵营/%E5%8D%A1%E8%A5%BF%E7%B1%B3%E5%B0%94.html","identities":[{"title":"1. 竞技骑士","text":"你在商业联赛中搏杀，胜场决定了你得到的赞助与声望。你可能被迫地配合媒体营销，或苦恼于应付各路记者和赞助商。\n\n额外装备：竞技骑士证件，自选熟练的简易武器\n\n额外技能：运动\n\n起源专长：凶蛮打手 或 健壮"},{"title":"2. 商业代表","text":"你为所属的赞助商或企业拉取合作机会、处理竞猜盘口、广告合约或骑士转会。你习惯于用合同与金钱解决多数问题。\n\n额外装备：企业雇员证件，高档服装（西装），香水，公文包\n\n额外技能：游说\n\n起源专长：幸运"},{"title":"3. 无胄盟线人","text":"你为那些灰色组织收集情报，或者是处理脏活，你清楚为了活下来，时刻保持警觉非常重要。毕竟对你而言，任何人都不值得信任。\n\n额外装备：自选熟练的简易远程武器，5弩矢，记事本（名单）\n\n额外技能：察觉\n\n起源专长：警觉"},{"title":"4. 城镇居民","text":"你在贫民窟挣扎求生，或者隐藏感染者身份在竞技场后台或企业工厂维护设备。你的薪资微薄，或是穷困潦倒，总是得不到良好的医疗保障。\n\n额外装备：撬棍，通用抑制剂，口粮（2日份）\n\n额外技能：巧手\n\n起源专长：健壮 或 警觉"},{"title":"5. 卡西米尔：自定义背景","text":"启用《塔莎的万事坩埚》扩展中的定制规则的战役，允许了玩家角色创作自己的自定义背景。在这种情况下，他们可以自己创作自己的背景身份设定，自选从背景中获得的属性值提升、装备、技能熟练以及起源专长。不过这种创作仍必须有一定的合理性，也就是创作的背景需要和他们所选的装备、技能和专长有一定叙事上的关联。\n\n属性值提升：任意\n\n额外装备：无\n\n额外技能：自选一项技能\n\n起源专长：自选一项起源专长"}]},{"label":"维多利亚","name":"维多利亚","english":"Victoria","abilities":"体质，智力，魅力","feat":"取决于身份","skills":"任选1项技能","tool":"自选工匠工具 或 书法工具 或 文书伪造工具","equipment":"(A)：怀表，旅行服装，茶叶罐，32GP； (B)：50GP","description":"君主制国家维多利亚强调霸权与扩张，旨在建立以维多利亚为中心的世界体系，开创一个属于维多利亚的全新时代。维多利亚是一个多种族国家，主要种族为菲林，阿斯兰、德拉克以及瓦伊凡通常是维多利亚的贵族以及统治阶层。然而，如今的维多利亚已经在连年的政治斗争中失去国王，以及他们最引以为傲的精锐兵种蒸汽骑士许多年，也曾一度陷入疲敝和战争的危机。伦蒂尼姆战争以后，维多利亚在重新达成协调的议会及各大公爵的管理下，以伦蒂尼姆为首都，通过管辖权广阔的骑警队以及开放更为宽松的地区自治政策来维持国内各方势力的平衡。\n\n维多利亚内部的阶级以及感染者矛盾依然存在，大多数感染者被强制隔离，私藏感染者同属于重罪，在更严重的地区仍有感染者被直接处刑的情况发生。不过，维多利亚在部分工业城市中政策上对感染者的态度会更为缓和。伦蒂尼姆在战争过后激增的感染者数量，也迫使着议会不得不重新审视以前曾经订立过的感染者管制条例。\n\n阵营身份：从以下几种预设身份中选择一种，然后获得对应的额外装备、技能熟练和起源专长。你也可以自己编造新的身份。","url":"https://astratide.github.io/ROH-online/topics/第二章：角色资源/阵营/%E7%BB%B4%E5%A4%9A%E5%88%A9%E4%BA%9A.html","identities":[{"title":"1. 近卫学院","text":"你受训于皇家近卫学院或其他高等军事学院，接受过完整的战术指挥与格斗训练，并以纪律和荣誉为傲。学院的课程涵盖移动城邦防御工事解析、贵族礼仪规范及感染者管制条例。你相信这些在学校习得的战术与仪态可以用以报效国家，或者在其他地方派上用场。你可能在毕业后服役于维多利亚典范军或是担任地方军官，或是效忠于某公爵，又或是更谨慎地保持中立。\n\n额外装备：学院证书，自选熟练的简易近战武器\n\n额外技能：运动\n\n起源专长：凶蛮打手 或 健壮"},{"title":"2. 公爵特工","text":"你为某位大贵族执行秘密任务，渗透议会之间，清除敌对者或者搜集其他地区的情报。有时候你会以商人、记者或外交随员身份渗透敌对势力，通过贿赂、勒索或清除手段维护自身阵营的利益。你清楚自己的身份需要绝对保密，否则将牵连甚广。不过，有时候接到的任务简报，依然会让你开始怀疑自己所作所为的必要性和正当性。\n\n额外装备：文书伪造工具，毒药小瓶，微型监控装置\n\n额外技能：欺瞒\n\n起源专长：幸运"},{"title":"3. 城区帮众","text":"你在贫民窟或工厂区争夺地盘，帮派或许是你唯一庇护和归属。一些帮派会收取保护费或是在地区横向霸道，而另一些帮派则更像是贫民窟自发组建的互助会。作为帮众的一员，你可能参与过械斗甚至是地区走私，也面对过恼人的官吏或是其他势力的虎视眈眈。但这些大多仍在你的认知范围之内——直到你所生存的城镇迎来了你未曾意想过的剧烈变化。\n\n额外装备：指虎，爪勾，绳索\n\n额外技能：求生\n\n起源专长：酒馆斗殴者"},{"title":"4. 城镇居民","text":"你在移动城邦中经营小店或是担任文员，或是依靠一门赖以为生的手艺汲汲营营，又或者是在枯燥的工作中寻求转变。在维多利亚经济衰退以及战争复燃的那些年，让你清晰地意识到了荣耀是不能拿来当饭吃的。虽然，在帝国议会的管理下维多利亚各郡的经济确实有复苏的迹象，但你仍不得不忍受着高昂的税项老实本分地工作，安慰着自己起码这里秩序尚存。\n\n额外装备：记事本（账本），自选工具\n\n额外技能：调查\n\n起源专长：巧匠 或 幸运"},{"title":"5. 维多利亚：自定义背景","text":"启用《塔莎的万事坩埚》扩展中的定制规则的战役，允许了玩家角色创作自己的自定义背景。在这种情况下，他们可以自己创作自己的背景身份设定，自选从背景中获得的属性值提升、装备、技能熟练以及起源专长。不过这种创作仍必须有一定的合理性，也就是创作的背景需要和他们所选的装备、技能和专长有一定叙事上的关联。\n\n属性值提升：任意\n\n额外装备：无\n\n额外技能：自选一项技能\n\n起源专长：自选一项起源专长"}]},{"label":"拉特兰","name":"拉特兰","english":"Laterano","abilities":"敏捷、感知、魅力","feat":"取决于身份","skills":"任选1项技能","tool":"自选乐器 或 书法工具","equipment":"(A)：自选熟练的远程武器（可以是铳械），书籍（圣典），高档服装，8GP； (B)：50GP","description":"拉特兰是以律法与信仰立国的中立宗教国家，主要公民种族通常是萨科塔或黎博利，拉特兰唯一的城市圣城由教皇厅管理运作，繁荣富足，素有地上天堂的美誉。一种被称为律法的规条，是拉特兰大部分公共权力的合理来源，包括教宗在内的拉特兰政府人员均以践行律法的名义行使权力。尽管数千年来拉特兰未曾被战火侵染，但训练有素且尽责尽职的拉特兰戍卫队，依然和作为精锐的教宗铳骑们组成了拉特兰不可忽视的强大军事力量。\n\n热爱甜食与枪弹的萨科塔们将铳械武装相关课程列入了公民教育体系中，并在年满十二岁时为每位公民授予铳械或其他铳型武装，以此形成了独特的守护铳文化。而全民医疗保障，以及普及的医院和矿石病检测设备使得拉特兰的人均寿命几乎是泰拉最高。自然地，圣城居民们皆骄傲于拉特兰的繁盛、自由、安定和富足。\n\n在感染者权力方面，虽然公民在感染矿石病后其权益仍得到保留，但感染者通常并不被允许继续在拉特兰的领土内居住或逗留，并在离境后继续定期受到补贴和药物。在万国信使制度建立后，拉特兰官方也开始改变以往的外交政策，积极地与泰拉诸国建立联系，邀请各国使节参与万国峰会，共同商讨安全和危机应对事宜，并协调各国主张。\n\n“拉特兰，这里是乐园，这里是奇迹，无数城邦与王国困于战火，转瞬即逝，唯有拉特兰永世长存”\n\n阵营身份：从以下几种预设身份中选择一种，然后获得对应的额外装备、技能熟练和起源专长。你也可以自己编造新的身份。","url":"https://astratide.github.io/ROH-online/topics/第二章：角色资源/阵营/%E6%8B%89%E7%89%B9%E5%85%B0.html","identities":[{"title":"1. 公证所执行者","text":"拉特兰教廷第五厅公证所外派的执行者可以出现在泰拉的任何角落，保障拉特兰公民的权益，并督促他们履行公民义务。历经专业训练，你懂得如何快速追缉罪犯或完成公证任务。你的任务目标通常是拉特兰公民本人或者是其指定的其他人，而在公证任务或追缉任务中，你往往需要长途跋涉前往某地寻找任务目标，来交托或收回某物或某信息（又或者是将目标抓捕归案）。\n\n额外装备：公证所证件，记事本（名单），自选铳械配件\n\n额外技能：洞悉\n\n起源专长：警觉"},{"title":"2. 万国信使","text":"由拉特兰主导建立的国际外交组织万国信使，旨在通过吸纳不同种族、身份、理念的人才成为特遣联络官，持教皇厅签署的通行证件，前往各国完成不同的外交任务，不限于联系诸国的主张和诉求，调停武装冲突或是进行危机预警。万国信使有着极为严苛的选拔标准和资历要求，也必须承担起为拉特兰代言的责任和危险。无论如何，你早已作好接受挑战的准备。\n\n额外装备：万国信使证件，记事本，指南针，卷铺，旅行服装\n\n额外技能：游说\n\n起源专长：幸运"},{"title":"3. 修道院修士","text":"你在拉特兰修道院研习律法圣典与神学。职责包括抄写经文、打扫修道院，以及照顾或教导修道院的孩子们。你还习得了一些可以帮助他人的小法术，可以在教徒祈祷时起到帮助。虽然院长以及修女们平时非常照顾你，但你偶尔也会为了修道院的未来而发愁。毕竟，没有任何修道院的成员希望这座曾经养育了许多希望的修道院，再次面对关闭的危机。\n\n额外装备：长袍，圣徽，圣水，书法工具\n\n额外技能：宗教\n\n起源专长：魔法学徒（牧师）或 \n源石技艺天赋"},{"title":"4. 铳械工匠","text":"你在官方许可的工坊制造或维护铳械，从民用礼仪式铳到公证所特制狙击铳皆经你手。你熟悉每一处机械构造，制造和保养的流程，最后将制作精良的铳械送到它们的主人手上。你对铳械有着特殊的情感，或者在其上寄托了远大的期望。有时候你也会因为一些特殊订单，而被卷入意想不到的困境和斗争之中——但你知道应该怎么处理这些麻烦。\n\n额外装备：铁匠工具，自选铳械配件\n\n额外技能：求生\n\n起源专长：熟习 或 \n巧匠"},{"title":"5. 拉特兰公民","text":"你在圣区经营小店或是担任文职，你的公民权益受律法保护，早已经习惯生活被爆炸声和甜品的味道充斥每一处角落。对于拉特兰出生长大的人来说，往往很难理解圣城之外的人所遭遇的苦难，因为这是他们自出身起就未体验过的滋味。但有时，你仍会怀疑圣城的律法有着其不足之处，并且进一步渴望了解圣城与其他城市差异的原因。\n\n额外装备：记事本（账本），自选工具，10GP\n\n额外技能：调查\n\n起源专长：巧匠 或 幸运"},{"title":"5. 拉特兰：自定义背景","text":"启用《塔莎的万事坩埚》扩展中的定制规则的战役，允许了玩家角色创作自己的自定义背景。在这种情况下，他们可以自己创作自己的背景身份设定，自选从背景中获得的装备、技能熟练以及起源专长。不过这种创作仍必须有一定的合理性，也就是创作的背景需要和他们所选的装备、技能和专长有一定叙事上的关联。\n\n属性值提升：任意\n\n额外装备：无\n\n额外技能：自选一项技能\n\n起源专长：自选一项起源专长"}]},{"label":"伊比利亚","name":"伊比利亚","english":"Iberia","abilities":"敏捷、体质、感知","feat":"取决于身份","skills":"任选1项技能","tool":"领航工具 或 自选工匠工具","equipment":"(A)：厚重大衣，附盖提灯，2扁瓶燃油，口粮（3日份），怀表，8GP； (B)：50GP","description":"伊比利亚是一个临海宗教国家，制度相对保守封闭，大多数原住民种族为黎博利，以及少量斐迪亚。在大静谧之前，也曾有许多被称为岛民的阿戈尔人来到岸上，与伊比利亚宫廷科学院一起完成了诸多科技成果。过去的伊比利亚曾无比繁荣，流传有黄金国度的美名，被与热情、活力、奢豪，以及洒满海岸的阳光联系在一起，但近些年伊比利亚的活动逐渐沉寂，不再与其他国家联系。\n\n在大静谧事件以后，海岸线沦陷，伊比利亚宫廷以及大部分沿海城市完全失联，科技、文化以及经济均发生了严重的断层。如今，由国教会改组而成的审判庭依靠惩戒军重新掌控了残存移动城邦的秩序，并派遣熟习教义的教士们管理地方城镇。在新秩序下，伊比利亚逐渐变得压抑且封闭，即便陆地资源匮乏，民众也被禁止出海，而那些曾经带来繁盛科技的阿戈尔岛民们，都被视为了灾厄源头。\n\n在伊比利亚之眼灯塔的重启以及阿戈尔航道计划启动后，伊比利亚疲敝的现状开始好转。然而，深海教会以及其他境外势力仍潜伏在境内，尝试破坏伊比利亚的复兴。\n\n阵营身份：从以下几种预设身份中选择一种，然后获得对应的额外装备、技能熟练和起源专长。你也可以自己编造新的身份。","url":"https://astratide.github.io/ROH-online/topics/第二章：角色资源/阵营/%E4%BC%8A%E6%AF%94%E5%88%A9%E4%BA%9A.html","identities":[{"title":"1. 审判庭代行者","text":"伊比利亚审判庭外派的代行者小队隶属于惩戒军编制，由审判官带领，负责对内的秩序维护和对抗来自海嗣的威胁。尽管如此，在需要追查境外渗透实力以及遗失的重要遗物时，代行者们仍会谨慎地出现在伊比利亚境外展开调查。作为审判庭的一员，你惯于从那些看似日常的细节中寻找你需要的信息，并排除掉那些可能会对伊比利亚复兴造成不利的因素。\n\n额外装备：镀银刺剑，审判庭证件，记事本（名单）\n\n额外技能：宗教\n\n起源专长：警觉"},{"title":"2. 灯塔看守者","text":"伊比利亚几乎每个沿海城镇都建立起了超过一座灯塔，但不是每一座灯塔都能从大静谧的余波当中幸存。伊比利亚人从灾难中习得了对大海的敬畏和恐慌，数十年来不再有人出海——你清楚知晓这些林立于海岸线的灯塔已经不再被需要了。但在伊比利亚繁盛不再的今天，你仍畅想着有朝一日可以重新点亮这些失落的灯塔，为航船指引前路，并再次为伊比利亚带来希望的光芒。\n\n额外装备：望远镜，信号笛，领航工具\n\n额外技能：察觉\n\n起源专长：幸运"},{"title":"3. 习武教士","text":"你在审判庭监督下进行战斗训练与布道。在伊比利亚宗教重新成为精神寄托的今天，被称为主教或者教士的人，相比起圣职人员更像是基层民政工作者，通过讲经布道这种更富有感染力的形式，来为民众生活提供指导。为了保证教士以及居民们的人身安全，习武教士一职应运而生，在伊比利亚百废待兴的各个城镇中，担任起了形似基层民警的治安维护以及纷争协调的作用。\n\n额外装备：书籍（圣典），自选熟练的简易武器\n\n额外技能：宗教\n\n起源专长：凶蛮打手 或 \n健壮"},{"title":"4. 退潮拾荒者","text":"在如今的伊比利亚，人们普遍恐惧乃至排斥大海，盲目地遵循教典以及教士的指导，但你更为叛逆。你清晰地明白海洋深处隐藏着的巨大秘密和财富，也习惯于避开审判庭的监视下，潜入退潮后的污染区，在此处打捞旧时代金属或是奇异的海鱼。有时候你会发现自己的身体出现了轻微的异化，但你不在乎——填饱肚子和挣钱比什么都重要。\n\n额外装备： 自选工具，2小包，铲子，5GP\n\n额外技能：求生\n\n起源专长：巧匠 或 幸运"},{"title":"5. 伊比利亚：自定义背景","text":"启用《塔莎的万事坩埚》扩展中的定制规则的战役，允许了玩家角色创作自己的自定义背景。在这种情况下，他们可以自己创作自己的背景身份设定，自选从背景中获得的属性值提升、装备、技能熟练以及起源专长。不过这种创作仍必须有一定的合理性，也就是创作的背景需要和他们所选的装备、技能和专长有一定叙事上的关联。\n\n属性值提升：任意\n\n额外装备：无\n\n额外技能：自选一项技能\n\n起源专长：自选一项起源专长"}]},{"label":"大炎","name":"大炎","english":"Yan","abilities":"敏捷、感知、魅力","feat":"取决于身份","skills":"任选1项技能","tool":"自选乐器 或 书法工具 或 自选工匠工具","equipment":"(A)：旅行服装，口粮（3日），40GP； (B)：50GP","description":"大炎是实行中央集权制度的东方孤立帝国，疆土广阔，历史深远，文化多样。炎国属于多民族国家，几乎可以在大炎找到任何泰拉种族的居民。此外，龙以及麒麟等神民种也被视为炎国王室或是贵族种族。数千年来历经更迭和权力变动，但作为最高统治者的皇帝一职，即大炎真龙，依然在境内享有极高的威信和掌控力。由皇帝、内阁以及六部构成的大炎朝廷以百灶为首都，通过复杂的下级官僚机构，以及实力强大拱卫中央的禁军，来管理整个国家多达十九个行政区，以及近千座移动城镇。\n\n大炎的城市规模和人口数量相较于其他国家显著地更加庞大，多达近四亿的人口数量迫使大炎不得不采用移动城市和固定城市并行的策略，在土木天师们的帮助下铸起极为雄伟的城市规模建设。如今的大炎几乎每座移动城市都有着自给自足的能力，而地方驻军也给予了城市极大的安全保障。\n\n在感染者政策方面，大炎对于感染者的政策非常宽松，即便受感染，只要登记在册便可正常继续享受公民权益。此外，得益于先进的科技以及天师们高超的法术造诣，大炎内部许多地区极少发生严重天灾，因此感染者数量也并不多。\n\n阵营身份：从以下几种预设身份中选择一种，然后获得对应的额外装备、技能熟练和起源专长。你也可以自己编造新的身份。","url":"https://astratide.github.io/ROH-online/topics/第二章：角色资源/阵营/%E5%A4%A7%E7%82%8E.html","identities":[{"title":"1. 钦天监信使","text":"钦天监虽属六部之下，但仍是地位最为特殊的一个大炎官方机构。除了一般意义上的气象观测，钦天监也司掌大炎全域的天灾预报事宜，向全国以及周边地区差遣天灾信使，协调受灾地区的人员物资。钦天监所设立的观测台旨在及时发现天灾的形成，并将预警通报送达对应的城市，为移动城市撤出天灾影响区域留出时间。此外，钦天监偶尔也会外派天灾勘测队伍，长期在荒漠里跋涉，为移动城镇绘制合适的安全航道以及进行实地调查。\n\n额外装备：钦天监令牌，记事本（天灾观测数据）\n\n额外技能：自然\n\n起源专长：警觉"},{"title":"2. 镖局镖师","text":"炎国境内四通八达的驰道将不同的城镇连接起来，但也不意味着商旅可以畅通无忧。匪患以及流寇在地方聚落徘徊，通行者的人身安全不得不依靠接受委托的镖师小队来保护。镖局是受人钱财，凭藉武功，专门为人运送货物书信或保障人身安全的机构，与信使却有着本质的不同。镖局背后牵扯的势力与利益关系错综复杂，可以说与江湖武林以及大炎朝廷都有着千丝万缕的关系——毕竟干这行就注定了要惹麻烦。\n\n额外装备：镖局证件，自选熟练的简易武器，卷铺，旅行服装\n\n额外技能：运动\n\n起源专长：健壮"},{"title":"3. “春乾”天灾救援队","text":"“春乾”是炎国官方成立的天灾救援组织，主要在大炎北方的天灾易发地区进行救援活动。在那些性命攸关的时刻，只有你们可以为那些遭遇天灾的地区带来所急需的物资和人手支援。尽管任务危险，但救援队成员早已立志投身于从天灾之下拯救生命的崇高事业。此外，在周边国家遭遇大型天灾时，救援队们也会在力能所及的情况下伸出人道主义援手。\n\n额外装备：背包，毯子，铁壶，手电筒\n\n额外技能：医药 或 求生\n\n起源专长：健壮"},{"title":"4. 天师府学徒","text":"天师府学徒们在官府设立的天师府修习源石技艺，专攻不同的技艺方向，例如土木工程或是气象调控。天师府的考校标准严苛，往往仅对那些展现出优秀源石技艺天赋，并在专业知识的掌握能力上具备高度可塑性的人开放。迈入这扇门后，将成为授业天师的门生，在这里独过长达数年乃至十数年的修行时光。最终，这些艰苦的修行都将在炎国的土地上证明其价值。\n\n额外装备：自选工具，法术卷轴（自选戏法）\n\n额外技能：奥秘 或 自然\n\n起源专长：源石技艺天赋 或 \n魔法学徒（法师）"},{"title":"5. 大炎：自定义背景","text":"启用《塔莎的万事坩埚》扩展中的定制规则的战役，允许了玩家角色创作自己的自定义背景。在这种情况下，他们可以自己创作自己的背景身份设定，自选从背景中获得的属性值提升、装备、技能熟练以及起源专长。不过这种创作仍必须有一定的合理性，也就是创作的背景需要和他们所选的装备、技能和专长有一定叙事上的关联。\n\n属性值提升：任意\n\n额外装备：无\n\n额外技能：自选一项技能\n\n起源专长：自选一项起源专长"}]},{"label":"哥伦比亚","name":"哥伦比亚","english":"Columbia","abilities":"智力、感知、魅力","feat":"取决于身份","skills":"任选1项技能","tool":"陆运载具 或 黑客工具","equipment":"(A)：手表，旅行服装，记事本，42GP； (B)：50GP","description":"哥伦比亚是联邦制新兴国家，在从维多利亚帝国独立以后，由在马克·麦克斯总统的领导下开始急速地发展。在制度方面，哥伦比亚的行政系统由民选总统与作为立法与监督机构的联合议会共同执政，为州政府及企业财团之前进行制衡。整个哥伦比亚依靠科技研发与资本扩张推动国家发展，移动城邦在各种前沿技术的不断投入中不断升级，而拓荒团队依然在持续勘探未开发地带。\n\n哥伦比亚的军事力量主要由国防部的职业常备军，和外包的私人军事承包商共同组成。士兵们以精良的制式武器装备，高速战舰支持下的机械化步兵师作为主要作战编制。哥伦比亚主要社会矛盾包括州法律与联邦政策的冲突、拓荒者资源纠纷、企业科技监管缺失等。\n\n在感染者权益方面，哥伦比亚对感染者采取监管就业政策，允许其进入高危行业工作。尽管联邦条例规定了矿石病感染者拥有平等公民权，但哥伦比亚的感染者依然需要购买一种昂贵的特殊医疗保险计划，定期缴纳保金。否则就可能被执法部门强迁至感染者收治区——或者，他们的另一条路是与政府或大企业签订拓荒合同，冒着生命危险为后者在危险的荒野上开疆拓土。\n\n阵营身份：从以下几种预设身份中选择一种，然后获得对应的额外装备、技能熟练和起源专长。你也可以自己编造新的身份。","url":"https://astratide.github.io/ROH-online/topics/第二章：角色资源/阵营/%E5%93%A5%E4%BC%A6%E6%AF%94%E4%BA%9A.html","identities":[{"title":"1. 拓荒队成员","text":"你受雇于企业或政府，深入未开发的荒野勘探资源、建立前哨或执行安保任务。拓荒工作危险重重，你要面对恶劣环境、未知威胁以及装备补给的压力，但回报也可能相当丰厚。你可能需要面对危险的荒野上游荡的野兽、天灾和匪帮的威胁的同时，与其他拓荒对伙伴一起种植作物、狩猎野兽、勘探和发掘矿脉、购置车辆等。许多哥伦比亚的感染者选择这份工作是为了偿还保险债务或寻求一条生路。\n\n额外装备：盾牌，源石电池，防护服，企业证件\n\n额外技能：求生\n\n起源专长：健壮"},{"title":"2. 企业特派员","text":"你代表财团与政府机构协商合作项目。你善于分析竞争对手方案，通过游说议员推动有利政策。你可能需要参加重要会议、商务应酬，同时也要暗中为企业收集情报，以实现各种商业目标。你的任务常在法律的灰色地带游走，需要灵活应对各种突发状况。此外，对于一些严格的企业而言，如果雇员的业绩未达标，那么被调往边缘分公司也是可能的事情。\n\n额外装备：企业证件，提神剂，文件夹（合同），公文包\n\n额外技能：游说\n\n起源专长：熟习"},{"title":"3. 私人军事公司/安保承包商","text":"大型私人军事公司，为企业财团、拓荒队或政府部门提供有偿的武装安保、战术支援或区域控制服务。你可能在特定企业的安保部门担任护卫或防御人员，或者在私人军事公司作为职业佣兵行动。虽然你的工作有着较高的风险，但好在公司提供了先进装备和战术培训，福利体系也较为完善。\n\n额外装备：自选你熟练军用武器（至多20GP），企业证件，防护服\n\n额外技能：察觉\n\n起源专长：警觉"},{"title":"4. 科研实习生","text":"你在联邦实验室或者私人科研公司利用自己的理论知识，参与前沿的科研项目。你可能会和团队一起源石技艺应用、工程学或生物科技。虽然你可能经验尚浅，只能做一些维护实验设备参数、校准机械或者是泡咖啡之类的工作。在更为深入的科研领域，研究员们通常需要思考自己工作的伦理边界。\n\n额外装备：企业证件，放大镜，笔记本（实验报告），高档服装，防护服\n\n额外技能：奥秘\n\n起源专长：魔法学徒（法师） 或 源石技艺天赋 或 巧匠"},{"title":"5. 哥伦比亚：自定义背景","text":"启用《塔莎的万事坩埚》扩展中的定制规则的战役，允许了玩家角色创作自己的自定义背景。在这种情况下，他们可以自己创作自己的背景身份设定，自选从背景中获得的属性值提升、装备、技能熟练以及起源专长。不过这种创作仍必须有一定的合理性，也就是创作的背景需要和他们所选的装备、技能和专长有一定叙事上的关联。\n\n属性值提升：任意\n\n额外装备：无\n\n额外技能：自选一项技能\n\n起源专长：自选一项起源专长"}]},{"label":"叙拉古","name":"叙拉古","english":"Siracusa","abilities":"体质、敏捷、魅力","feat":"取决于身份","skills":"任选1项技能","tool":"盗贼工具 或 自选赌具","equipment":"(A)：旅行服装，自选工具或赌具，30GP； (B)：50GP","description":"位于泰拉中部的叙拉古是由多个自治城邦组成的联合体，疆域涵盖了包括热带林区以及荒原等多种地貌。尽管在从莱塔尼亚帝国独立以后，叙拉古的十二家族曾有过血腥而残酷的斗争历史。但在现代叙拉古，由西西里夫人所带来的“铳与秩序”，已经构成起了家族之间的严谨而残酷的秩序和界限。在灰厅的威慑下，家族的权力和斗争都能只归于暗面——而在明面上，叙拉古的秩序则可以有限度地，由城邦联合的议事会及法院所构成的行政机关所维持。\n\n叙拉古的人口主体主要是由鲁珀族构成，生活在叙拉古的鲁珀通常有着强烈的家族观念和排外意识，也促成了当地盛行的家族和黑手党文化。此外，在本地享有美名的叙拉古戏剧和传统美食也是叙拉古人们的骄傲之一。\n\n在感染者政策方面，叙拉古的感染者政策与哥伦比亚类似，感染者需缴纳巨额的保险金才被允许正常生活。无法缴纳的感染者可能会被家族成员或者城邦法官驱逐到其他灰色地区。\n\n阵营身份：从以下几种预设身份中选择一种，然后获得对应的额外装备、技能熟练和起源专长。你也可以自己编造新的身份。","url":"https://astratide.github.io/ROH-online/topics/第二章：角色资源/阵营/%E5%8F%99%E6%8B%89%E5%8F%A4.html","identities":[{"title":"1. 家族成员","text":"你在某个家族权力体系中担任执行者或管理者，也可能只是普通的打手。你的日常工作可能包括了监督账目收支、押运重要货物或充当线人收集情报。你也对街头斗殴以及持械战斗具有一定经验。不过，如果你作出了任何有违家族利益的举动，也可能遭到家族派来的清道夫的追剿。\n\n额外装备：家族纹章，高档服装\n\n额外技能：欺瞒 或 \n威吓\n\n起源专长：酒馆斗殴者"},{"title":"2. 法务助理","text":"你在城邦法院系统担任文书或庭审记录员，也可以作为执法者逮捕犯人。你的工作涉及整理卷宗、核验证据。对你而言，单纯的调解商户纠纷和登记财产契约还算可以处理，但如果某个案件涉及到家族利益或成员，那你可要小心了——法官们尚且能在灰厅的庇护下自保，而法务助理们却往往是家族报复和刺杀的重点关照对象。\n\n额外装备：法院证件，书籍（法典），公文包\n\n额外技能：调查\n\n起源专长：熟习"},{"title":"3. 清道夫","text":"作为黑手党家族在暗处的执行者，你直属家族首领指挥，负责执行各种见不得光的任务。人们称你们为“清道夫”，因为你们总能让问题像从未存在过一样被抹去。你在行动前会从中间人处获取目标信息和工具，完成任务后凭信物领取酬金。你的工作需要精准、冷酷和绝对的谨慎，常年游走在暗处也让你习惯观察城市的阴影角落。\n\n额外装备：自选熟练军用武器，高档服装，家族纹章\n\n额外技能：隐匿\n\n起源专长：警觉"},{"title":"4. 离群之狼","text":"离群之狼们因背叛、失败或主动逃离而失去了家族的庇护，他们在叙拉古西部危险的荒原地带活动。与阴雨连绵的叙拉古东部城市不同，这里物资匮乏，少有人烟。你或许在荒野之上搜寻旧时代遗物、稀有矿物或失踪商队的物资。你要避开游荡的\"狼群\"、巡逻队和源石污染区，独来独往，或与少数可信伙伴合作。这份工作没有家族庇护，但自由无价。\n\n额外装备：盗贼工具，背包，口粮（3日）\n\n额外技能：求生\n\n起源专长：健壮"},{"title":"5. 叙拉古：自定义背景","text":"启用《塔莎的万事坩埚》扩展中的定制规则的战役，允许了玩家角色创作自己的自定义背景。在这种情况下，他们可以自己创作自己的背景身份设定，自选从背景中获得的属性值提升、装备、技能熟练以及起源专长。不过这种创作仍必须有一定的合理性，也就是创作的背景需要和他们所选的装备、技能和专长有一定叙事上的关联。\n\n属性值提升：任意\n\n额外装备：无\n\n额外技能：自选一项技能\n\n起源专长：自选一项起源专长"}]},{"label":"萨米","name":"萨米","english":"Sami","abilities":"体质、感知、魅力","feat":"取决于身份","skills":"任选1项技能","tool":"草药工具 或 自选工匠工具","equipment":"(A)：旅行服装，槲寄生枝条，毯子，地图，帐篷，30GP； (B)：50GP","description":"位于泰拉大陆北境的萨米是由一个神秘和自然的冰雪国度，疆域涵盖了包括北方的群山、中部的林地以及南部的沼泽等多种地貌。在“族树”的带领下，萨米的各个部族以相当传统的方式在各种严峻的自然环境中生活着，通过狩猎、采集以及以物易物的贸易方式维系着部族的存续。\n\n萨米南部因哥伦比亚贸易飞地的存在而有限开放，已经有萨米人建立起了许多频繁和乌萨斯以及哥伦比亚商队贸易的小镇（例如知名的萨米小镇察帕特），经营着旅游业和售卖本土特产、药材，已经让他们可以过上富足的生活。然而，萨米更广大的中北部地区，仍由排外的部落牢牢控制，外人想进入通常需要获得雪祀的许可。\n\n萨米的人口主体主要是由埃拉菲亚构成。萨米人的文化上有着对自然环境的敬畏，还有对灵魂的重视。他们相信万物有灵，对所有生物都秉持尊重的态度。他们将自身部族的族树视为极为重要的存在，这些蕴含着奇特力量的巨树被视为祖灵“安玛”的恩赐，几乎每个部族都环绕着族树而生存着。\n\n当前，整个萨米面临的最严峻挑战来自于北部因非冰原持续涌出的“邪魔”，各部族的精锐战士长期在冬牙山脉一带构筑防线，以阻止其南下。此外，在萨米南方的乌萨斯也对萨米的领土虎视眈眈，时有试图侵占萨米领土和掠走萨米人的行径。\n\n在感染者政策方面，萨米部落普遍表现出比其他地区更高的包容性，感染者通常不会被驱逐，而是由部落的巫医尝试进行照料。或许是因为萨米严酷的自然环境，这里的矿石病人很少，即便有也不会受到异样的目光。\n\n阵营身份：从以下几种预设身份中选择一种，然后获得对应的额外装备、技能熟练和起源专长。你也可以自己编造新的身份。","url":"https://astratide.github.io/ROH-online/topics/第二章：角色资源/阵营/%E8%90%A8%E7%B1%B3.html","identities":[{"title":"1. 萨满","text":"曾作为部族的萨满，你知晓如何通过占卜决定部族迁徙的时机与方向、主持重要的祭祀仪式、解读族树上生成的密文，以获取来自萨米向你们传达跨越时间和空间的启示。你见证过雄伟的族树如何在雪祀的召唤下，根系连同林地一起拔地而起，在萨米的土地上带领着部族一同迁徙。祖灵之树的感召、密文的解读又或是叛逆的本性让你离开了曾经的部族，但你知道你总有一天会再次回来。\n\n额外装备：紫衫魔杖，圣徽（部族护身符），书籍（树谱）\n\n额外技能：自然 或 奥秘\n\n起源专长：魔法学徒（德鲁伊）"},{"title":"2. 巡林客","text":"你在萨米复杂而危险的林区、山地与湿地中担任向导与搜救者。你深谙如何在暴风雪中辨识方向，如何避开不稳定的冰层与隐藏的沼泽，并熟悉各类北方特有野兽的习性。你曾见过迷路的哥伦比亚勘察队员、遭遇天灾的商队，或是与本部落走散的族人。你可能是少数能够被中北部部落所接纳和信任的外来者之一。\n\n额外装备：短弓，箭袋，信号笛，铁蒺藜，绳索\n\n额外技能：调查\n\n起源专长：熟习"},{"title":"3. 边民","text":"你曾在部落中作为一名普通成员生活，可能是一名猎人、草药师或工匠。你的生活与族树紧密相连，遵循着古老的习俗与雪祀的指引。你懂得如何利用环境中的资源：采集药草治疗伤痛，设置陷阱捕捉猎物，利用毛皮和皮革制作衣物与帐篷。你亲身经历过乌萨斯边防军的骚扰，也知晓北方邪魔是何等可怕的存在。部落的自给自足能力，基本都依赖于你和你族人们的劳动。\n\n额外装备：匕首，背包，口粮（3日）\n\n额外技能：自然 或 求生\n\n起源专长：健壮"},{"title":"4. 萨米：自定义背景","text":"启用《塔莎的万事坩埚》扩展中的定制规则的战役，允许了玩家角色创作自己的自定义背景。在这种情况下，他们可以自己创作自己的背景身份设定，自选从背景中获得的属性值提升、装备、技能熟练以及起源专长。不过这种创作仍必须有一定的合理性，也就是创作的背景需要和他们所选的装备、技能和专长有一定叙事上的关联。\n\n属性值提升：任意\n\n额外装备：无\n\n额外技能：自选一项技能\n\n起源专长：自选一项起源专长"}]}]};
